    Flow.Name = "Flow Kan Hub"
    Flow.Version = "1.14.40"
    Flow.Services = {}
    Flow.Features = {}
    Flow.Runtime = {
        connections = {},
        currentPage = "overview",
        gui = nil,
    }

    local function getService(name)
        local ok, service = pcall(function()
            return game:GetService(name)
        end)
        return ok and service or nil
    end

    Flow.Services.Workspace = getService("Workspace")
    Flow.Services.Players = getService("Players")
    Flow.Services.TweenService = getService("TweenService")
    Flow.Services.RunService = getService("RunService")
    Flow.Services.TeleportService = getService("TeleportService")
    Flow.Services.UserInputService = getService("UserInputService")
    Flow.Services.ReplicatedStorage = getService("ReplicatedStorage")
    Flow.Services.CollectionService = getService("CollectionService")
    Flow.Services.Lighting = getService("Lighting")
    Flow.Services.VirtualInputManager = getService("VirtualInputManager")
    Flow.Services.VirtualUser = getService("VirtualUser")
    Flow.Services.HttpService = getService("HttpService")
