    function Flow:GetExecutorFunction(name)
        local ok, value = pcall(function()
            local environment = getgenv and getgenv() or nil
            return type(environment) == "table" and environment[name] or nil
        end)
        if ok and type(value) == "function" then return value end

        local globalValue = rawget(_G, name)
        if type(globalValue) == "function" then return globalValue end
        return nil
    end

