        readfile = Flow:GetExecutorFunction("readfile"),
        writefile = Flow:GetExecutorFunction("writefile"),
        isfile = Flow:GetExecutorFunction("isfile"),
        keypress = Flow:GetExecutorFunction("keypress"),
        keyrelease = Flow:GetExecutorFunction("keyrelease"),
        firesignal = Flow:GetExecutorFunction("firesignal"),
    }

