    end

    function Flow:Destroy()
        -- Stop the live collector and invalidate its current loop, but keep the
        -- separately persisted autoCollectEnabled preference for a future load.
        local finder = self.Features and self.Features.FruitFinder
        if finder and finder.SetAutoCollect then
            pcall(function() finder:SetAutoCollect(false) end)
