        elseif self.State then
            self.State.isTeleporting = false
        end
        local misc = self.Features and self.Features.Misc
        if misc and misc.Shutdown then pcall(function() misc:Shutdown() end) end
        local priority = self.Features and self.Features.SystemPriority
        if priority and priority.Shutdown then pcall(function() priority:Shutdown() end) end
        local telemetry = self.Features and self.Features.SystemTelemetry
        if telemetry and telemetry.Shutdown then pcall(function() telemetry:Shutdown() end) end
        local farm = self.Features and self.Features.Farm
        if farm and farm.Shutdown then pcall(function() farm:Shutdown() end) end
        local raid = self.Features and self.Features.Raid
        if raid and raid.Shutdown then pcall(function() raid:Shutdown() end) end
        local raidMonitor = self.Features and self.Features.RaidMonitor
        if raidMonitor and raidMonitor.Shutdown then pcall(function() raidMonitor:Shutdown() end) end
        local notifications = self.Features and self.Features.Notifications
        if notifications and notifications.Shutdown then pcall(function() notifications:Shutdown() end) end
