;(function(Flow)
    local visual = Flow.RayfieldVisual or {}
    local Theme = {
        -- Offline Rayfield-style surfaces, kept in Flow's required red theme.
        bg = visual.background or Color3.fromRGB(10, 11, 16),
        panel = visual.surface or Color3.fromRGB(18, 20, 28),
        panel2 = visual.elevated or Color3.fromRGB(25, 28, 38),
        panel3 = visual.control or Color3.fromRGB(33, 37, 49),
        accent = visual.accent or Color3.fromRGB(220, 49, 65),
        accent2 = visual.accentStrong or Color3.fromRGB(248, 77, 91),
        text = visual.text or Color3.fromRGB(245, 246, 250),
        muted = visual.muted or Color3.fromRGB(166, 172, 188),
        success = visual.success or Color3.fromRGB(78, 198, 133),
        danger = visual.accentStrong or Color3.fromRGB(248, 77, 91),
        border = visual.border or Color3.fromRGB(50, 54, 68),
        corner = visual.corner or 10,
        cardGap = visual.cardGap or 10,
    }

    function Theme.New(className, properties)
        local object = Instance.new(className)
        for property, value in pairs(properties or {}) do
            object[property] = value
        end
        return object
    end

    function Theme.Round(parent, radius)
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, radius or Theme.corner or 10)
        corner.Parent = parent
        return corner
    end

    function Theme.Stroke(parent, color, thickness, transparency)
        local stroke = Instance.new("UIStroke")
        stroke.Color = color or Theme.border
        stroke.Thickness = thickness or 1
        stroke.Transparency = transparency or 0
        stroke.Parent = parent
        return stroke
    end

    function Theme.Label(parent, text, size, color, bold)
        return Theme.New("TextLabel", {
            BackgroundTransparency = 1,
            Text = text or "",
            TextColor3 = color or Theme.text,
            TextSize = size or 10,
            Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = parent,
        })
    end

    function Theme.Button(parent, text, color)
        return Theme.New("TextButton", {
            Size = UDim2.new(0, 100, 0, 26),
            BackgroundColor3 = color or Theme.accent,
            BorderSizePixel = 0,
            Text = text or "",
            TextColor3 = Theme.text,
            TextSize = 10,
            Font = Enum.Font.GothamBold,
            AutoButtonColor = true,
            Parent = parent,
        })
    end

    function Theme.Toggle(parent, initialState, callback)
        local tweenService = Flow.Services.TweenService
        local state = initialState and true or false
        local track = Theme.New("Frame", {
            Size = UDim2.new(0, 40, 0, 20),
            BackgroundColor3 = state and Theme.accent or Color3.fromRGB(44, 32, 34),
            BorderSizePixel = 0,
            Active = true,
            Parent = parent,
        })
        Theme.Round(track, 10)

