;(function(Flow)
    local Servers = {}
    local teleportService = Flow.Services.TeleportService
    local players = Flow.Services.Players
    local player = Flow.Player

    Servers.Seas = {
        {key = "sea1", label = "Sea 1", placeId = 2753915549},
        {key = "sea2", label = "Sea 2", placeId = 4442272183},
        {key = "sea3", label = "Sea 3", placeId = 7449423635},
    }

    local function trim(value)
        return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    end

    function Servers:GetSea(key)
        for _, sea in ipairs(self.Seas) do
            if sea.key == key then return sea end
        end
        return nil
    end

    function Servers:GetCurrentJobId()
        return tostring((game and game.JobId) or "")
    end

    function Servers:GetInfo()
        local count, maximum = 0, 0
        if players and players.GetPlayers then
            local ok, list = pcall(function() return players:GetPlayers() end)
            if ok and type(list) == "table" then count = #list end
            maximum = tonumber(players.MaxPlayers) or 0
        end
        local privateId = tostring((game and game.PrivateServerId) or "")
        return {
            jobId = self:GetCurrentJobId(),
            placeId = tonumber((game and game.PlaceId) or 0) or 0,
            placeVersion = tonumber((game and game.PlaceVersion) or 0) or 0,
            playerCount = count,
            maxPlayers = maximum,
            serverType = privateId ~= "" and "private" or "public",
        }
    end

    function Servers:TravelSea(key)
        local sea = self:GetSea(key)
        if not sea then return false, "sea_unknown" end
        if not teleportService or not player then return false, "teleport_service_missing" end
        local ok, detail = pcall(function()
            if type(teleportService.Teleport) == "function" then
                return teleportService:Teleport(sea.placeId, player)
            end
            return teleportService:TeleportAsync(sea.placeId, {player})
        end)
        return ok, detail or sea
    end

    function Servers:Hop()
        if not teleportService or not player then return false, "teleport_service_missing" end
        local placeId = tonumber((game and game.PlaceId) or 0) or 0
        if placeId <= 0 then return false, "place_missing" end
        -- TeleportService chooses an eligible public instance. No server-list
        -- endpoint, game Remote, clipboard, or hidden server browser is used.
        local ok, detail = pcall(function()
            if type(teleportService.Teleport) == "function" then
                return teleportService:Teleport(placeId, player)
            end
            return teleportService:TeleportAsync(placeId, {player})
        end)
        return ok, detail
    end

    function Servers:Rejoin()
        if not teleportService or not player then return false, "teleport_service_missing" end
        local placeId = tonumber((game and game.PlaceId) or 0) or 0
        if placeId <= 0 then return false, "place_missing" end
        local jobId = self:GetCurrentJobId()
        local ok, detail = pcall(function()
            if jobId ~= "" and type(teleportService.TeleportToPlaceInstance) == "function" then
                return teleportService:TeleportToPlaceInstance(placeId, jobId, player)
            end
            if type(teleportService.Teleport) == "function" then
                return teleportService:Teleport(placeId, player)
            end
            return teleportService:TeleportAsync(placeId, {player})
        end)
        return ok, detail
    end

    function Servers:JoinJob(jobId)
        jobId = trim(jobId)
        if jobId == "" then return false, "job_missing" end
        if #jobId > 160 or not string.match(jobId, "^[%w%-_]+$") then
            return false, "job_invalid"
        end
        if not teleportService or not player then return false, "teleport_service_missing" end
        local placeId = tonumber((game and game.PlaceId) or 0) or 0
        if placeId <= 0 then return false, "place_missing" end
        local ok, detail = pcall(function()
            return teleportService:TeleportToPlaceInstance(placeId, jobId, player)
        end)
        return ok, detail
    end

    Flow.Features.TravelServers = Servers
end)(Flow)

