        local height = clamp(tonumber(heightOverride) or self:GetHoverHeight(), 8, 80)
        local now = os.clock()
        if mode == "orbit" then
            local radius = clamp(tonumber(State.farmControlDistance) or 15, 8, 30)
            return CFrame.new(center + Vector3.new(math.cos(now * 3.5) * radius, height, math.sin(now * 3.5) * radius))
        elseif mode == "star" then
