        local getItems = cache and cache.GetItems
        if type(getItems) ~= "function" then return results end
        local got, quantities = pcall(function() return cache:GetItems("Quantity") end)
        if not got or type(quantities) ~= "table" then return results end
        -- `GetItems("Quantity")` has hundreds of unordered entries on a
        -- mature account. The previous first-160 cutoff could randomly miss
        -- physical fruit entries (whose item IDs are currently near 1400),
        -- while the equipped Portal Moveset was correctly excluded. Build a
        -- bounded, deterministic list before metadata lookup instead.
        local entries = {}
        for _, entry in pairs(quantities) do
            local itemId = type(entry) == "table" and entry.ItemId or nil
            local count = type(entry) == "table" and tonumber(entry.Value) or 0
            if itemId and count > 0 then table.insert(entries, { itemId = itemId, count = count }) end
        end
        table.sort(entries, function(left, right)
            local leftId, rightId = tonumber(left.itemId), tonumber(right.itemId)
            if leftId and rightId and leftId ~= rightId then return leftId < rightId end
            return tostring(left.itemId) < tostring(right.itemId)
        end)
        local scanLimit = math.min(#entries, 512)
        for position = 1, scanLimit do
            local entry = entries[position]
            local itemId, count = entry.itemId, entry.count
            local matched, record = pcall(function()
                local result = config.match and config.match(itemId)
                return result and result.unwrap and result:unwrap() or nil
            end)
            local index = matched and record and record.Index or nil
            local label = index and (index.DebugLabel or index.Name) or nil
            local idType = index and tostring(index.IdType or "") or ""
            -- `Moveset` is an already consumed/equipped ability (such as
            -- Portal-Portal). `PhysicalMoveset` is the only stored fruit type
            -- eligible for the Raid payment and is intentionally exclusive.
            if idType == "PhysicalMoveset" then
                local loadName = tostring(label or itemId):gsub("%s*%b[]", "")
                local fruit = self:ResolveFruit(loadName)
                if fruit and self:IsFruitAllowed(fruit) then
                    local key = normalize(loadName)
                    if not seen[key] then
                        seen[key] = true
                        table.insert(results, { fruit = fruit, name = loadName, source = "stored", itemId = itemId, count = count })
                    end
                end
            end
        end
        return results
    end

    function Raid:PickRaidFruit()
        local candidates = self:GetHeldRaidFruits()
        for _, entry in ipairs(self:GetStoredRaidFruits()) do table.insert(candidates, entry) end
        table.sort(candidates, function(left, right)
            local leftRank = self.FruitRanks[left.fruit.rarity] or 99
            local rightRank = self.FruitRanks[right.fruit.rarity] or 99
            if leftRank == rightRank then return left.fruit.name < right.fruit.name end
            return leftRank < rightRank
        end)
        return candidates[1]
    end

    function Raid:LoadStoredFruit(choice)
        if not choice or choice.source ~= "stored" then return true, choice end
        local ok, detail = self:CallCommF("LoadFruit", choice.name)
        if not ok then return false, "fruit_load_failed:" .. tostring(detail) end
        local deadline = os.clock() + 3
        repeat
            local fruit = self:ResolveFruit(choice.name)
            for _, held in ipairs(self:GetHeldRaidFruits()) do
                if held.fruit == fruit then return true, held end
            end
            task.wait(0.10)
        until os.clock() >= deadline or not self.State.running
        return false, "fruit_load_not_confirmed"
    end

    function Raid:EquipRaidFruit(choice)
        local tool, humanoid, character = choice and choice.tool, currentHumanoid(), currentCharacter()
        if not tool or not humanoid or not character then return false, "fruit_tool_or_character_missing" end
        if tool.Parent ~= character then
            local ok, detail = pcall(function() humanoid:EquipTool(tool) end)
            if not ok then return false, "fruit_equip_failed:" .. tostring(detail) end
            task.wait(0.12)
        end
        if tool.Parent ~= character then return false, "fruit_equip_not_confirmed" end
        return true, "fruit_equipped"
    end

    function Raid:PrepareRaidFruit(choice)
        if not choice then return false, "raid_fruit_missing_or_blocked" end
        self:SetPhase("loading_fruit", choice.fruit.name)
        self:SetChipDecision("fruit_selected|" .. choice.fruit.name .. "|" .. tostring(choice.source))
        local loaded, loadReason = self:LoadStoredFruit(choice)
        if not loaded then
            self:SetChipDecision("fruit_load_failed|" .. tostring(loadReason))
            return false, loadReason
        end
        local heldChoice = loadReason
        local equipped, equipReason = self:EquipRaidFruit(heldChoice)
        if not equipped then
            self:SetChipDecision("fruit_equip_failed|" .. tostring(equipReason))
            return false, equipReason
        end
        self.State.selectedFruit = heldChoice.fruit and heldChoice.fruit.name or nil
        self:SetChipDecision("fruit_equipped|" .. tostring(self.State.selectedFruit) .. "|" .. tostring(heldChoice.source))
        return true, heldChoice
    end

    function Raid:IsPhysicalFruitCooldown(response)
        local text = tostring(response or ""):lower()
        return text:find("cooldown", 1, true) ~= nil and text:find("physical fruit", 1, true) ~= nil
    end

    function Raid:RequestRaidChip(method, selectedFruit)
        self:SetPhase("buying_chip", State.raidType or "Flame")
        local called, response = self:CallCommF("RaidsNpc", "Select", State.raidType or "Flame")
        self.State.lastChipResponse = tostring(response or "")
        if not called then
            self:SetChipDecision("chip_request_failed|" .. tostring(response))
            return false, "raid_chip_request_failed:" .. tostring(response), response
        end
        if method == "beli" and self:IsPhysicalFruitCooldown(response) then
            self:SetChipDecision("beli_cooldown_requires_fruit|response=" .. tostring(response))
            return false, "raid_chip_beli_cooldown", response
        end
        if method == "fruit_beli_cooldown" and self:IsPhysicalFruitCooldown(response) then
            -- A physical fruit was actually loaded/equipped, yet the known
            -- server contract still rejected it. Latch this result so the
            -- controller does not loop purchase/equip attempts every step.
            self.State.chipCooldownBlocked = true
            self.State.chipCooldownBlockedUntil = os.clock() + self.ChipPhysicalRetrySeconds
            self.State.chipRetryAt = self.State.chipCooldownBlockedUntil
            self:SetChipDecision("physical_fruit_request_rejected|retry_after=" .. tostring(self.ChipPhysicalRetrySeconds) .. "|response=" .. tostring(response))
            return false, "raid_chip_physical_fruit_request_rejected", response
        end
        self:SetChipDecision("chip_requested|method=" .. tostring(method) .. "|" .. tostring(State.raidType or "Flame") .. "|response=" .. tostring(response))
        local deadline = os.clock() + 3.5
        repeat
            if self:GetChip() then
                self.State.selectedFruit = nil
                self.State.chipObservedAt = os.clock()
                self:SetChipDecision("chip_confirmed|" .. tostring(method) .. "|" .. tostring(selectedFruit and selectedFruit.fruit and selectedFruit.fruit.name or ""))
                return true, "chip_confirmed", response
            end
            task.wait(0.10)
        until os.clock() >= deadline or not self.State.running
        self:SetChipDecision("chip_not_confirmed|method=" .. tostring(method) .. "|response=" .. tostring(response))
        return false, "raid_chip_not_confirmed:" .. tostring(response), response
    end

    function Raid:DeferChipAttempt(reason, seconds)
        seconds = math.max(5, tonumber(seconds) or self.ChipRequestRetrySeconds)
        self.State.chipRetryAt = os.clock() + seconds
        self:SetChipDecision(tostring(reason) .. "|retry_after=" .. tostring(seconds))
        return false, tostring(reason) .. "|retry_after=" .. tostring(seconds)
    end

    function Raid:EnsureChip()
        -- Defensive backstop: Step normally handles these two states before
        -- calling EnsureChip, but neither may ever cause a duplicate purchase.
        if self:IsRaiding() then return false, "world_raid_active" end
        if self.State.chipCommitted == true then return false, "raid_start_committed" end
        if self:GetChip() then
            self.State.chipCooldownBlocked = false
            self.State.chipCooldownBlockedUntil = 0
            self.State.chipRetryAt = 0
            if not self.State.chipObservedAt or self.State.chipObservedAt <= 0 then self.State.chipObservedAt = os.clock() end
            self:SetChipDecision("chip_ready|existing")
            return true, "chip_ready"
        end
        if self.State.chipCooldownBlocked then
            local remaining = (self.State.chipCooldownBlockedUntil or 0) - os.clock()
            if remaining > 0 then return false, "raid_chip_physical_fruit_retry_wait:" .. tostring(math.ceil(remaining)) end
            self.State.chipCooldownBlocked = false
            self.State.chipCooldownBlockedUntil = 0
        end
        local retryRemaining = (self.State.chipRetryAt or 0) - os.clock()
        if retryRemaining > 0 then return false, "raid_chip_retry_wait:" .. tostring(math.ceil(retryRemaining)) end
        self.State.chipObservedAt = 0
        local beli = self:GetBeli()
        local moneyThreshold = math.max(self.MinimumBeli, tonumber(State.raidMoneyThreshold) or self.MinimumBeli)
        local fruitEnabled = State.raidUseFruitWhenLowMoney == true
        local useFruit = fruitEnabled and beli < moneyThreshold
        if useFruit then
            local prepared, choiceOrReason = self:PrepareRaidFruit(self:PickRaidFruit())
            if not prepared then return self:DeferChipAttempt(choiceOrReason, self.ChipUnavailableRetrySeconds) end
            local bought, buyReason = self:RequestRaidChip("fruit_low_beli", choiceOrReason)
            if bought then return true, buyReason end
            if self.State.chipCooldownBlocked then return false, buyReason end
            return self:DeferChipAttempt(buyReason, self.ChipRequestRetrySeconds)
        end

        self.State.selectedFruit = nil
        self:SetChipDecision("beli_selected|beli=" .. tostring(beli) .. "|threshold=" .. tostring(moneyThreshold) .. "|fruit_option=" .. tostring(fruitEnabled))
        local bought, buyReason, response = self:RequestRaidChip("beli", nil)
        if bought then return true, buyReason end

        -- The observed fixed RaidsNpc response explicitly instructs use of a
        -- physical fruit during the Beli-chip cooldown. Honor it once, only
        -- when the user's fruit fallback option is on and a permitted fruit is
        -- actually present; CallCommF keeps the normal 1.05-second spacing.
        if fruitEnabled and self:IsPhysicalFruitCooldown(response) then
            self:SetChipDecision("beli_cooldown_requires_fruit|response=" .. tostring(response))
            local prepared, choiceOrReason = self:PrepareRaidFruit(self:PickRaidFruit())
            if not prepared then return self:DeferChipAttempt(choiceOrReason, self.ChipUnavailableRetrySeconds) end
            local fruitBought, fruitReason = self:RequestRaidChip("fruit_beli_cooldown", choiceOrReason)
            if fruitBought then return true, fruitReason end
            if self.State.chipCooldownBlocked then return false, fruitReason end
            return self:DeferChipAttempt(fruitReason, self.ChipRequestRetrySeconds)
        end
        return self:DeferChipAttempt(buyReason, self.ChipRequestRetrySeconds)
    end

    function Raid:EnsureRaidSummonAccess()
        if self:IsRaiding() then return true, "world_raid_active" end
        local root = currentRoot()
        if not root then return false, "root_missing" end
        local distance = (root.Position - self.SummonPosition).Magnitude
        if distance <= self.SummonAccessRadius then return true, "summon_area" end
        if not teleport or not teleport.TravelDirectToPosition then return false, "movement_unavailable" end
        -- A Raid direct route owns movement. Release only a Raid-owned lease;
        -- the shared Teleport module performs cancellation, collision cleanup,
        -- retry and arrival confirmation.
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
        self:SetPhase("going_to_summon", "castle_on_the_sea|distance=" .. tostring(math.floor(distance + 0.5)))
        local moved, reason = teleport:TravelDirectToPosition(self.SummonPosition, "raid", "Raid summon Castle on the Sea")
        if moved then
            self:Trace("summon_travel", "arrived|" .. tostring(self.SummonPosition))
            return true, "summon_arrived"
        end
        self:Trace("summon_travel", "failed|" .. tostring(reason))
        return false, reason or "summon_travel_failed"
    end

    function Raid:GetStartDetector()
        local map = workspace and workspace:FindFirstChild("Map")
        local sea = self:GetSea()
        local path = sea == 2 and "CircleIsland.RaidSummon2.Button.Main" or (sea == 3 and "Boat Castle.RaidSummon2.Button.Main" or nil)
        local main = map and path and findPath(map, path) or nil
        local detector = main and main:FindFirstChild("ClickDetector")
        local position = main and main:IsA("BasePart") and main.Position or nil
        if not position and main and main:IsA("Model") then
            local ok, pivot = pcall(function() return main:GetPivot() end)
            position = ok and pivot and pivot.Position or nil
        end
        return detector, sea, position
    end

    function Raid:IsNativeRaidArrivalConfirmed()
        -- IslandRaiding alone is not enough: it is set server-side before
        -- the native character teleport can reach this client. A local route
        -- in that window strands Root in Castle air and can chase remote NPCs.
        if not self:IsRaiding() then return false, "server_raid_not_active" end
        local root = currentRoot()
        if not root then return false, "root_missing" end
        local castleDistance = (root.Position - self.SummonPosition).Magnitude
        if castleDistance <= self.NativeTransferCastleRadius then
            return false, "native_transfer_waiting_at_castle|distance=" .. tostring(math.floor(castleDistance + 0.5))
        end
        for _, island in ipairs(self:GetRaidIslands()) do
            local distance = (root.Position - island.position).Magnitude
            if distance <= self.NativeTransferIslandRadius then
                return true, "native_raid_island_" .. tostring(island.id)
            end
        end
        -- Map markers can stream a moment after the character. Since every
        -- Hub route is locked during this period, a far Root can only be the
        -- game's native transfer and is a safe final confirmation.
        if castleDistance >= self.NativeTransferFarFallback then
            return true, "native_raid_transfer_far_from_castle"
        end
        return false, "native_transfer_waiting_for_island|distance=" .. tostring(math.floor(castleDistance + 0.5))
    end

    function Raid:HoldForNativeRaidTransfer(detail)
        -- Remove every local movement/hover lease while native replication is
        -- settling. This is intentionally a hold, never a fallback travel.
        if teleport and teleport.CancelTravel then pcall(function() teleport:CancelTravel("raid", "native_raid_transfer_wait") end) end
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
        if farm and farm.ClearHover then pcall(function() farm:ClearHover() end) end
        self:SetPhase("awaiting_native_raid_teleport", tostring(detail or "native_transfer_waiting"))
    end

    function Raid:StartRaid()
        if self:IsRaiding() then return true, "already_active" end
        if not self:GetChip() then return false, "chip_missing" end
        local now = os.clock()
        if now < (self.State.awaitingStartUntil or 0) then
            self:SetPhase("awaiting_raid_start", "confirming_summon")
            return true, "confirming_summon"
        end
        if now - (self.State.lastStartAt or -math.huge) < self.StartRetrySeconds then
            -- The normal raid flow needs time to replicate IslandRaiding after
            -- the known ClickDetector action. Keep the UI in an explicit wait
            -- state instead of overwriting it with a generic preflight/error.
            self:SetPhase("awaiting_raid_start", "awaiting_server")
            return true, "start_cooldown"
        end
        if (self.State.startAttempts or 0) >= self.MaxStartAttempts then return false, "start_retry_limit" end
        local detector, sea = self:GetStartDetector()
        local attempts = self.State.startAttempts or 0
        -- A chip must never turn into an autonomous route to an Island or a
        -- summon pad. The source routine submits its known click and waits for
        -- the game to transition the local player into Raid. If the surface is
        -- not streamed, wait for that surface instead of moving the character.
        if not detector then
            self:SetPhase("awaiting_raid_start", (sea == 2 or sea == 3) and "summon_surface_waiting" or "raid_sea_unavailable")
            return true, "summon_surface_waiting"
        end
        local fireClick = Flow:GetExecutorFunction("fireclickdetector")
        if not fireClick then return false, "fireclickdetector_unavailable" end
        if attempts == 0 then self:CaptureIslandBaseline() end
        -- Ensure the completed Castle approach cannot retain a local tween/
        -- hover lease across the game's own Raid teleport.
        if teleport and teleport.CancelTravel then pcall(function() teleport:CancelTravel("raid", "before_native_raid_summon") end) end
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
        if farm and farm.ClearHover then pcall(function() farm:ClearHover() end) end
        self:ClearOwnedRaidSession()
        self.State.startedByController = true
        self.State.lastStartAt = now
        self.State.awaitingStartUntil = now + self.StartObserveSeconds
        self.State.startAttempts = attempts + 1
        local ok, detail = pcall(fireClick, detector)
        if not ok then
            self.State.awaitingStartUntil = 0
            self.State.startAttempts = attempts
            return false, "raid_summon_click_failed:" .. tostring(detail)
        end
        -- From this point the pre-click chip is committed to this one Raid.
        -- Do not call EnsureChip again until the server Raid has ended.
        self.State.chipCommitted = true
        self.State.chipCommittedAt = now
        self.State.nativeTransferStartedAt = now
        self.State.nativeTransferConfirmed = false
        local root = currentRoot()
        self.State.nativeTransferOrigin = root and root.Position or nil
        self:SetPhase("awaiting_native_raid_teleport", "summon_clicked|chip_committed|waiting_for_native_transfer")
        return true, "summon_clicked"
    end

    function Raid:GetRaidIslands()
        local results = {}
        local origin = workspace and workspace:FindFirstChild("_WorldOrigin")
        local locations = origin and origin:FindFirstChild("Locations")
        if not locations then return results end
        local checked = 0
        for _, item in ipairs(locations:GetChildren()) do
            checked = checked + 1
            if checked > 80 then break end
            local id = tostring(item.Name):match("^Island%s*(%d+)$")
            local position = item:IsA("BasePart") and item.Position or nil
            if not position and item:IsA("Model") then
                local ok, pivot = pcall(function() return item:GetPivot() end)
                position = ok and pivot and pivot.Position or nil
            end
            if id and position then table.insert(results, { object = item, id = tonumber(id), position = position }) end
        end
        table.sort(results, function(left, right) return left.id < right.id end)
        return results
    end

    -- Raid islands are globally replicated and do not expose an owner attribute.
    -- Bind a controller-created Raid to markers added after its own summon, then
    -- extend only through spatially linked markers. This prevents a different
    -- player's Island N from becoming a movement/combat target.
    function Raid:CaptureIslandBaseline()
        local state = self.State
        state.islandBaseline, state.ownedIslands, state.ownedIslandOrder = {}, {}, {}
        state.ownershipMode, state.ownershipDetail = nil, ""
        for _, island in ipairs(self:GetRaidIslands()) do state.islandBaseline[island.object] = true end
    end

    function Raid:ClearOwnedRaidSession()
        local state = self.State
        state.ownedIslands, state.ownedIslandOrder = {}, {}
        state.ownershipMode, state.ownershipDetail = nil, ""
        state.activeIsland, state.activeIslandId = nil, nil
        if self.ClearCombatWave then self:ClearCombatWave("session_cleared") end
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
    end

    -- The game ends IslandRaiding before the native return teleport arrives on
    -- this client. Do not clear the existing Raid hover on that edge: Flame
    -- ground is lava and a one-frame release is enough to take damage.
    function Raid:BeginNativeRaidReturnHold()
        local state, root = self.State, currentRoot()
        if not root then return false, "root_missing" end
        state.awaitingNativeReturn = true
        state.nativeReturnStartedAt = os.clock()
        state.nativeReturnOrigin = root.Position
        local center = state.safeCombatCenter
        if typeof(center) ~= "Vector3" then
            local island = state.activeIsland
            center = island and island.position or nil
        end
        if typeof(center) ~= "Vector3" then center = root.Position - Vector3.new(0, self:GetRaidHoverHeight(), 0) end
        state.nativeReturnHoldCenter = center
        state.v4ActivationDeadline = 0
        state.v4PromptPending = false
        self:ClearCombatWave("raid_finished_waiting_native_return")
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        self:Trace("native_return", "hold_started|origin=" .. tostring(state.nativeReturnOrigin) .. "|center=" .. tostring(center))
        return true, "native_return_hold_started"
    end

    function Raid:IsNativeRaidReturnConfirmed()
        local state, root = self.State, currentRoot()
        if not root then return false, "root_missing" end
        local origin = state.nativeReturnOrigin
        if typeof(origin) == "Vector3" then
            local moved = (root.Position - origin).Magnitude
            if moved >= self.NativeReturnRelocationDistance then
                return true, "native_return_relocated|distance=" .. tostring(math.floor(moved + 0.5))
            end
            return false, "waiting_native_return|distance=" .. tostring(math.floor(moved + 0.5))
        end
        return false, "waiting_native_return_origin_missing"
    end

    function Raid:HoldForNativeRaidReturn()
        local state, root = self.State, currentRoot()
        local center = state.nativeReturnHoldCenter
        if not root or typeof(center) ~= "Vector3" then return false, "return_hold_anchor_missing" end
        if farm and farm.BeginExternalHover then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalHover("raid", center, function()
                    -- Farm evaluates this immediately before each Heartbeat
                    -- CFrame write. If the game has just placed Root back in
                    -- the normal world, release first so hover can never
                    -- overwrite that native return teleport.
                    if self.State.running ~= true or self.State.awaitingNativeReturn ~= true then return false end
                    local returned = self:IsNativeRaidReturnConfirmed()
                    return returned ~= true
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "native_return_hover_unavailable" end
            return true, "native_return_raised_hover"
        end
        -- Never fall back to a local travel while waiting for the game's return.
        return false, "native_return_hover_unavailable"
    end

    function Raid:ClearNativeRaidReturnHold()
        local state = self.State
        state.awaitingNativeReturn = false
        state.nativeReturnOrigin = nil
        state.nativeReturnHoldCenter = nil
        state.nativeReturnStartedAt = 0
    end

    function Raid:AddOwnedIsland(island)
        if not island or not island.object or self.State.ownedIslands[island.object] then return false end
        self.State.ownedIslands[island.object] = island
        table.insert(self.State.ownedIslandOrder, island.object)
        return true
    end

    function Raid:GetOwnedRaidIslands()
        local results = {}
        for _, object in ipairs(self.State.ownedIslandOrder or {}) do
            local island = self.State.ownedIslands[object]
            if island and object and object.Parent then table.insert(results, island) end
        end
        table.sort(results, function(left, right) return left.id < right.id end)
        return results
    end

    function Raid:IsLinkedOwnedIsland(island)
        for _, known in ipairs(self:GetOwnedRaidIslands()) do
            if known.position and (known.position - island.position).Magnitude <= self.IslandClusterLinkRadius then return true end
        end
        return false
    end

    function Raid:ClaimOwnedRaidSession()
        local state, root = self.State, currentRoot()
        if not root then return false, "root_missing" end
        local candidates = {}
        for _, island in ipairs(self:GetRaidIslands()) do
            local isNew = state.islandBaseline[island.object] ~= true
            local eligible = state.startedByController and (isNew and island.id == 1) or (not state.startedByController)
            if eligible then
                local distance = (root.Position - island.position).Magnitude
                if distance <= self.InitialIslandAcquireRadius then table.insert(candidates, { island = island, distance = distance }) end
            end
        end
        if #candidates == 0 then return false, "owned_island_not_nearby" end
        table.sort(candidates, function(left, right)
            if left.distance == right.distance then return left.island.id < right.island.id end
            return left.distance < right.distance
        end)
        -- Do not guess between overlapping Raid clusters. The local HUD proves
        -- a Raid is active, not which equally-near marker belongs to it.
        if candidates[2] and math.abs(candidates[2].distance - candidates[1].distance) < 250 then return false, "owned_island_ambiguous" end
        self:AddOwnedIsland(candidates[1].island)
        state.ownershipMode = state.startedByController and "created" or "resumed"
        state.ownershipDetail = "island_" .. tostring(candidates[1].island.id)
        return true, state.ownershipDetail
    end

    function Raid:RefreshOwnedRaidIslands()
        local state, root = self.State, currentRoot()
        if not state.ownershipMode or not root then return false end
        local owned = self:GetOwnedRaidIslands()
        -- Extend from the furthest verified sequential marker, not the current
        -- combat marker, so Island 3 can be bound after Island 2 is observed.
        local current = owned[#owned]
        if not current then return false end
        local expectedId, candidates = (current.id or 0) + 1, {}
        for _, island in ipairs(self:GetRaidIslands()) do
            if not state.ownedIslands[island.object] and island.id == expectedId then
                local isNew = state.islandBaseline[island.object] ~= true
                local allowed = state.ownershipMode == "resumed" or isNew
                local rootDistance = (root.Position - island.position).Magnitude
                local linkDistance = (current.position - island.position).Magnitude
                if allowed and rootDistance <= self.IslandClusterLinkRadius and linkDistance <= self.IslandClusterLinkRadius then
                    table.insert(candidates, { island = island, rootDistance = rootDistance, linkDistance = linkDistance })
                end
            end
        end
        if #candidates == 0 then return #owned > 0 end
        table.sort(candidates, function(left, right)
            if left.rootDistance == right.rootDistance then return left.linkDistance < right.linkDistance end
            return left.rootDistance < right.rootDistance
        end)
        -- A same-number marker at a comparable distance is indistinguishable
        -- in replication. Fail closed rather than adding both or guessing.
        if candidates[2] and math.abs(candidates[2].rootDistance - candidates[1].rootDistance) < 250 then
            state.ownershipDetail = "next_island_ambiguous"
            return false
        end
        self:AddOwnedIsland(candidates[1].island)
        state.ownershipDetail = "island_" .. tostring(candidates[1].island.id)
        return true
    end

    function Raid:EnsureOwnedRaidSession()
        if not self.State.ownershipMode then
            local claimed, reason = self:ClaimOwnedRaidSession()
            if not claimed then
                self.State.ownershipDetail = reason
                return false, reason
            end
        end
        self:RefreshOwnedRaidIslands()
        return true, self.State.ownershipDetail
    end

    function Raid:GetOwnedIslandMobs(islands)
        local groups, enemies = {}, workspace and workspace:FindFirstChild("Enemies")
        for _, island in ipairs(islands or {}) do groups[island] = {} end
        if not enemies then return nil, {} end
        local checked = 0
        for _, enemy in ipairs(enemies:GetChildren()) do
            checked = checked + 1
            if checked > 120 then break end
            local root = modelRoot(enemy)
            if alive(enemy) and root then
                local nearest, nearestDistance = nil, math.huge
                for _, island in ipairs(islands or {}) do
                    local distance = (root.Position - island.position).Magnitude
                    if distance <= self.IslandMobRadius and distance < nearestDistance then nearest, nearestDistance = island, distance end
                end
                if nearest then table.insert(groups[nearest], { model = enemy, root = root, humanoid = enemy:FindFirstChildOfClass("Humanoid") }) end
            end
            if checked % 25 == 0 then task.wait() end
        end
        local best, bestMobs = nil, {}
        for _, island in ipairs(islands or {}) do
            local mobs = groups[island] or {}
            if #mobs > #bestMobs then best, bestMobs = island, mobs end
        end
        return best, bestMobs
    end

    function Raid:GetRaidMobs(island)
        local results = {}
        local enemies = workspace and workspace:FindFirstChild("Enemies")
        if not enemies or not island or typeof(island.position) ~= "Vector3" then return results end
        local checked = 0
        for _, enemy in ipairs(enemies:GetChildren()) do
            checked = checked + 1
            if checked > 120 then break end
            local root = modelRoot(enemy)
            if alive(enemy) and root and (root.Position - island.position).Magnitude <= self.IslandMobRadius then
                table.insert(results, { model = enemy, root = root, humanoid = enemy:FindFirstChildOfClass("Humanoid") })
            end
        end
        return results
    end

    -- The extracted raid routine approaches a live enemy before striking. Keep
    -- that behavior, but select only a natural cluster in the active island;
    -- the player anchor stays fixed over the cluster rather than following or
    -- changing any NPC.
    function Raid:GetNaturalRaidCluster(mobs)
        local best, bestCenter, bestDistance = {}, nil, math.huge
        local root = currentRoot()
        for _, seed in ipairs(mobs or {}) do
            if seed.root then
                local group = {}
                for _, candidate in ipairs(mobs) do
                    if candidate.root and (candidate.root.Position - seed.root.Position).Magnitude <= 55 then table.insert(group, candidate) end
                end
                local distance = root and (root.Position - seed.root.Position).Magnitude or 0
                if #group > #best or (#group == #best and distance < bestDistance) then
                    best, bestCenter, bestDistance = group, seed.root.Position, distance
                end
            end
        end
        return #best > 0 and best or nil, bestCenter
    end

    function Raid:ChooseIsland(islands, advance)
        if #islands == 0 then return nil end
        local root = currentRoot()
        local currentId = self.State.activeIslandId
        if advance and currentId then
            for _, island in ipairs(islands) do if island.id > currentId then return island end end
        end
        if root then
            local closest, distance = nil, math.huge
            for _, island in ipairs(islands) do
                local current = (root.Position - island.position).Magnitude
                if current < distance then closest, distance = island, current end
            end
            if closest then return closest end
        end
        return islands[1]
    end

    function Raid:GetRaidHoverHeight()
        -- Raid always uses its defensive overhead clearance. Farm may retain a
        -- separate user-selected height for ordinary level farming.
        return self.CombatHeight
    end

    function Raid:MoveAbove(position, label)
        local root = currentRoot()
        if not root or typeof(position) ~= "Vector3" then return false, "root_missing" end
        local destination = position + Vector3.new(0, self:GetRaidHoverHeight(), 0)
        if (root.Position - destination).Magnitude <= 100 then
            local ok, detail = pcall(function() root.CFrame = CFrame.new(destination) end)
            return ok, ok and "near_anchor" or tostring(detail)
        end
        if not teleport or not teleport.TravelDirectToPosition then return false, "movement_unavailable" end
        return teleport:TravelDirectToPosition(destination, "raid", label or "Raid island")
    end

    function Raid:MoveAndHoldAbove(position, label)
        local root = currentRoot()
        if not root or typeof(position) ~= "Vector3" then return false, "root_missing" end
        local destination = position + Vector3.new(0, self:GetRaidHoverHeight(), 0)
        if (root.Position - destination).Magnitude > 150 then
            -- A Tween and the Farm Heartbeat hover must never write Root.CFrame
            -- concurrently. Release the old combat lease before any travel;
            -- it is reacquired only after the travel returns.
            if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
            if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
            local moved, reason = self:MoveAbove(position, label)
            if not moved then return false, reason end
        end
        if farm and farm.BeginExternalHover then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalHover("raid", position, function()
                    return self.State.running == true and self:IsRaiding()
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "raid_hover_unavailable" end
            return true, "farm_settings_hover"
        end
        return self:MoveAbove(position, label)
    end

    -- The server's native Raid transfer may put the character at a low, unsafe
    -- landing point before the first owned marker or wave is replicated. This
    -- executes only after IsRaiding() is already true, uses the *new* Root
    -- location, then raises a fixed 40-stud air anchor. It never acts at the
    -- Castle before the native transfer.
    function Raid:HoldNativeRaidArrivalAboveCurrent(reason)
        local state, root = self.State, currentRoot()
        if not root then return false, "root_missing" end
        local center = state.arrivalHoldCenter
        if typeof(center) ~= "Vector3" then
            center = root.Position
            state.arrivalHoldCenter = center
            self:Trace("arrival_hover", tostring(reason or "native_arrival") .. "|center=" .. tostring(center))
        end
        if farm and farm.BeginExternalHover then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalHover("raid", center, function()
                    return self.State.running == true and self:IsRaiding()
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "raid_arrival_hover_unavailable" end
            return true, "native_arrival_raised_hover"
        end
        return self:MoveAndHoldAbove(center, "Native Raid arrival")
    end

    -- Before the very first wave, preserve the native arrival point while the
    -- local Raid streams. After a confirmed wave has been cleared, however,
    -- keeping that old point can leave Root near an island edge and prevent the
    -- next wave from streaming/spawning normally. Recenter X/Z on the verified
    -- owned island and apply the normal fixed Raid hover height from the island
    -- marker; Root's previous Y is deliberately never reused, so it cannot
    -- climb across consecutive empty-wave waits.
    function Raid:HoldWaveGapAboveCurrent(island)
        local state, root = self.State, currentRoot()
        if not root then return false, "root_missing" end
        local islandObject = island and island.object or nil
        local postWave = state.activeWaveSeen == true or state.resumedActiveRaid == true
        local center
        if postWave and island and typeof(island.position) == "Vector3" then
            center = island.position
            state.waveGapCenter = center
            state.waveGapIsland = islandObject
            local horizontal = Vector3.new(root.Position.X - center.X, 0, root.Position.Z - center.Z).Magnitude
            -- Within the verified inner island, the Raid hover can safely
            -- recenter in one lease update. This avoids a short direct-travel
            -- confirmation at a moving/falling Y coordinate, which could
            -- briefly report arrival_unconfirmed even though X/Z was centered.
            if horizontal <= self.SafeFollowIslandRadius and farm and farm.BeginExternalHover then
                local ok, held, detail = pcall(function()
                    return farm:BeginExternalHover("raid", center, function()
                        return self.State.running == true and self:IsRaiding()
                    end, self:GetRaidHoverHeight())
                end)
                if not ok or held ~= true then return false, detail or "raid_gap_center_hover_unavailable" end
                return true, "gap_centered_owned_island"
            end
            local held, detail = self:MoveAndHoldAbove(center, "Owned raid wave gap center")
            if not held then return false, detail or "raid_gap_center_unavailable" end
            return true, "gap_centered_owned_island"
        end
        -- Initial native entry: do not invent a local destination before the
        -- first owned wave has appeared and been verified.
        center = state.waveGapCenter
        if typeof(center) ~= "Vector3" or state.waveGapIsland ~= islandObject then
            center = state.arrivalHoldCenter
            if typeof(center) ~= "Vector3" then center = root.Position end
            state.waveGapCenter = center
            state.waveGapIsland = islandObject
        end
        if farm and farm.BeginExternalHover then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalHover("raid", center, function()
                    return self.State.running == true and self:IsRaiding()
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "raid_gap_hover_unavailable" end
            return true, "initial_gap_raised_static_hover"
        end
        return self:MoveAndHoldAbove(center, "Native Raid initial wave gap")
    end

    -- A live target is followed at Heartbeat frequency only while it remains
    -- inside the conservative inner radius of the owned island. If knockback
    -- carries it toward an edge, the provider immediately returns the last
    -- verified safe anchor instead of carrying the player into water/lava or
    -- releasing hover. It never stages, CFrames or otherwise mutates an NPC.
    -- A read-only surface sample is taken only when the guard detects an
    -- outward target. It runs against currently streamed geometry, unlike a
    -- post-respawn audit where a despawned raid island returns no ray hit.
    function Raid:ProbeHazardSurface(position, reason, ignoredModel)
        local state = self.State
        local now = os.clock()
        if typeof(position) ~= "Vector3" or now - (state.lastHazardSurfaceProbeAt or -math.huge) < 0.75 then return end
        state.lastHazardSurfaceProbeAt = now
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local ignored, character = {}, currentCharacter()
        if character then table.insert(ignored, character) end
        if ignoredModel then table.insert(ignored, ignoredModel) end
        params.FilterDescendantsInstances = ignored
        params.IgnoreWater = false
        local ok, result = pcall(function()
            return workspace:Raycast(position + Vector3.new(0, 500, 0), Vector3.new(0, -1000, 0), params)
        end)
        if ok and result then
            self:Trace("hazard_surface", tostring(reason) .. "|material=" .. tostring(result.Material)
                .. "|instance=" .. tostring(result.Instance and result.Instance:GetFullName())
                .. "|hit=" .. tostring(result.Position))
        else
            self:Trace("hazard_surface", tostring(reason) .. "|material=none|query=" .. tostring(position))
        end
    end

    function Raid:GetSafeRaidFollowCenter()
        local state = self.State
        local tracked = state.combatTarget
        local trackedRoot = tracked and modelRoot(tracked)
        local islandPosition = state.safeCombatIslandPosition
        local followLimit = self.SafeFollowIslandRadius
        if state.finalBossFollow == true and state.finalBossIsland == state.combatAnchorIsland
            and state.finalBossSurfaceSafe == true then
            followLimit = self.FinalBossFollowRadius
        end
        if self.State.running == true and self:IsRaiding() and alive(tracked)
            and trackedRoot and typeof(islandPosition) == "Vector3"
            and (trackedRoot.Position - islandPosition).Magnitude <= followLimit then
            state.safeCombatCenter = trackedRoot.Position
            return trackedRoot.Position
        end
        if self.State.running == true and self:IsRaiding() and alive(tracked) and trackedRoot
            and typeof(islandPosition) == "Vector3" then
            self:ProbeHazardSurface(trackedRoot.Position, "inner_follow_guard", tracked)
        end
        return state.safeCombatCenter
    end

    function Raid:HoldSafeCombatAnchor(island, reason)
        local state, root = self.State, currentRoot()
        local center = state.safeCombatCenter
        -- If this is the very first rejected sample, keep the current airborne
        -- point rather than guessing a ground/island-center location.
        if typeof(center) ~= "Vector3" and root then
            center = root.Position - Vector3.new(0, self:GetRaidHoverHeight(), 0)
            state.safeCombatCenter = center
        end
        if typeof(center) ~= "Vector3" then return false, "safe_anchor_missing" end
        state.combatActive = false
        state.combatMobs = {}
        state.combatTarget = nil
        if farm and farm.BeginExternalHover then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalHover("raid", center, function()
                    return self.State.running == true and self:IsRaiding()
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "raid_safe_hold_unavailable" end
            self:Trace("hazard_hold", tostring(reason or "out_of_bounds") .. "|center=" .. tostring(center))
            return true, "safe_anchor_hover"
        end
        return self:MoveAndHoldAbove(center, "Raid safe anchor")
    end

    function Raid:MoveAndFollowAbove(target, label)
        local root = currentRoot()
        local targetRoot = target and modelRoot(target)
        if not root or not targetRoot or not alive(target) then return false, "target_missing" end
        local position = self:GetSafeRaidFollowCenter()
        if typeof(position) ~= "Vector3" then return false, "safe_follow_anchor_missing" end
        local destination = position + Vector3.new(0, self:GetRaidHoverHeight(), 0)
        local separation = (root.Position - destination).Magnitude

        -- A target from the controller-verified local island is safe to take
        -- over directly within this bounded radius. This is deliberately wider
        -- than the old 150-stud Tween threshold, which released the hover lock
        -- during ordinary combat knockback and was observed to cause falls.
        if separation > self.FollowSnapDistance then
            if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
            if farm and farm.EndExternalHover then pcall(function() farm:EndExternalHover("raid") end) end
            local moved, reason = self:MoveAbove(position, label)
            if not moved then return false, reason end
            root = currentRoot()
            targetRoot = target and modelRoot(target)
            if not root or not targetRoot or not alive(target) then return false, "target_lost_after_travel" end
            position = self:GetSafeRaidFollowCenter()
            if typeof(position) ~= "Vector3" then return false, "safe_follow_anchor_missing" end
        end

        if farm and farm.BeginExternalFollow then
            local ok, held, detail = pcall(function()
                return farm:BeginExternalFollow("raid", position, function()
                    return self:GetSafeRaidFollowCenter()
                end, function()
                    return self.State.running == true and self.State.combatActive == true and self:IsRaiding()
                end, self:GetRaidHoverHeight())
            end)
            if not ok or held ~= true then return false, detail or "raid_follow_unavailable" end
            return true, "heartbeat_target_follow"
        end

        return self:MoveAndHoldAbove(position, label)
    end

    function Raid:ChooseWeapon()
        if not farm then return nil, "farm_unavailable" end
        local preferred = State.farmWeaponType
        local choices = { "Melee", "Sword" }
        if preferred == "Melee" or preferred == "Sword" then choices = { preferred } end
        for _, typeName in ipairs(choices) do
            local tool = farm:GetWeaponByType(typeName)
            if tool then
                self.State.effectiveWeapon = typeName
                return tool
            end
        end
        return nil, "weapon_missing"
    end

    function Raid:EquipWeapon()
        local tool, reason = self:ChooseWeapon()
        local humanoid = currentHumanoid()
        local character = currentCharacter()
        if not tool or not humanoid or not character then return nil, reason or "weapon_missing" end
        if tool.Parent ~= character then
            local ok, detail = pcall(function() humanoid:EquipTool(tool) end)
            if not ok then return nil, tostring(detail or "weapon_equip_failed") end
        end
        return tool
    end

    function Raid:UpdateAttackFeedback()
        local pending = self.State.pendingAttack
        if not pending or os.clock() - pending.at < self.CombatFeedbackInterval then return end
        local accepted = false
        for model, healthBefore in pairs(pending.health) do
            local humanoid = model and model:FindFirstChildOfClass("Humanoid")
            if not humanoid or humanoid.Health < healthBefore then accepted = true break end
        end
        if accepted then self.State.attackAccepted = self.State.attackAccepted + 1 else self.State.attackRejected = self.State.attackRejected + 1 end
        self.State.pendingAttack = nil
    end

    function Raid:GetCombatRemotes()
        local modules = replicatedStorage and replicatedStorage:FindFirstChild("Modules")
        local net = modules and modules:FindFirstChild("Net")
        local attack = net and net:FindFirstChild("RE/RegisterAttack")
        local hit = net and net:FindFirstChild("RE/RegisterHit")
        if attack and hit and attack:IsA("RemoteEvent") and hit:IsA("RemoteEvent") then return attack, hit end
        return nil, nil
    end

    -- The extracted reference uses the game's own SendHitsToServer function
    -- when the client advertises COMBAT_REMOTE_THREAD. Resolve that exact
    -- client-side pathway once per retry window and retain the known
    -- RegisterHit contract as a compatibility fallback.
    function Raid:GetSendHitsToServer()
        local state, now = self.State, os.clock()
        if type(state.sendHits) == "function" then return state.sendHits end
        if now < (state.sendHitsRetryAt or -math.huge) then return nil end
        state.sendHitsRetryAt = now + 2
        local getsenv = Flow:GetExecutorFunction("getsenv")
        local scripts = player and player:FindFirstChild("PlayerScripts")
        if type(getsenv) ~= "function" or not scripts then return nil end
        local checked = 0
        for _, script in ipairs(scripts:GetChildren()) do
            checked = checked + 1
            if checked > 100 then break end
            if script:IsA("LocalScript") then
                local ok, environment = pcall(getsenv, script)
                local sender = ok and environment and environment._G and environment._G.SendHitsToServer or nil
                if type(sender) == "function" then
                    state.sendHits = sender
                    state.sendHitsResolved = true
                    self:Trace("combat_path", "send_hits_to_server")
                    return sender
                end
            end
        end
        state.sendHitsResolved = false
        return nil
    end

    function Raid:HasCombatRemoteThread()
        local state = self.State
        if state.combatThreadAvailable ~= nil then return state.combatThreadAvailable == true end
        local flags = replicatedStorage and replicatedStorage:FindFirstChild("Modules") and replicatedStorage.Modules:FindFirstChild("Flags")
        local ok, values = pcall(function() return flags and require(flags) end)
        state.combatThreadAvailable = ok and type(values) == "table" and values.COMBAT_REMOTE_THREAD == true
        return state.combatThreadAvailable == true
    end

    function Raid:ClearCombatWave(reason)
        local state = self.State
        state.combatActive = false
        state.combatMobs = {}
        state.combatAnchor = nil
        state.combatAnchorIsland = nil
        state.combatTarget = nil
        state.finalBossFollow = false
        state.finalBossIsland = nil
        state.finalBossSurfaceSafe = false
        state.finalBossSurfaceDetail = ""
        state.finalBossGuardSignature = ""
        state.lastReanchorAt = -math.huge
        state.combatStageKey = nil
        state.pendingAttack = nil
        if reason then self:Trace("combat_wave", "cleared|" .. tostring(reason)) end
    end

    function Raid:GetNearestOwnedMob(mobs, origin)
        local best, distance = nil, math.huge
        for _, item in ipairs(mobs or {}) do
            if item and item.root and alive(item.model) then
                local current = origin and (item.root.Position - origin).Magnitude or 0
                if current < distance then best, distance = item, current end
            end
        end
        return best, distance
    end

    -- Keep a live owned target while it survives. Re-selecting the nearest mob
    -- every 0.25 seconds made the hover oscillate between knockback victims;
    -- a replacement is chosen only when the tracked model is no longer part of
    -- this controller-verified owned-island list.
    function Raid:GetTrackedOwnedMob(mobs, origin)
        local tracked = self.State.combatTarget
        if tracked then
            for _, item in ipairs(mobs or {}) do
                if item and item.model == tracked and item.root and alive(item.model) then
                    local distance = origin and (item.root.Position - origin).Magnitude or 0
                    return item, distance
                end
            end
        end
        return self:GetNearestOwnedMob(mobs, origin)
    end

    function Raid:GetCombatClusterForTarget(mobs, target)
        if not target or not target.root then return {} end
        if State.farmBringMobs ~= true then return { target } end
        local radius = math.max(60, math.min(600, tonumber(State.farmBringRadius) or 450))
        local group = {}
        for _, item in ipairs(mobs or {}) do
            if item and item.root and alive(item.model) and (item.root.Position - target.root.Position).Magnitude <= radius then
                table.insert(group, item)
                if #group >= 24 then break end
            end
        end
        return #group > 0 and group or { target }
    end

    -- Read only: reject an outer final-wave follow if its downward probe sees
    -- water, lava, no streamed support, or the target itself. Excluding the
    -- target model fixes the old false "Plastic / Flame Master torso" surface
    -- reading and makes this a true ground-safety decision.
    function Raid:IsSafeFinalBossSurface(position, ignoredModel)
        if typeof(position) ~= "Vector3" then return false, "position_missing" end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local ignored, character = {}, currentCharacter()
        if character then table.insert(ignored, character) end
        if ignoredModel then table.insert(ignored, ignoredModel) end
        params.FilterDescendantsInstances = ignored
        params.IgnoreWater = false
        local ok, hit = pcall(function()
            return workspace:Raycast(position + Vector3.new(0, 350, 0), Vector3.new(0, -800, 0), params)
        end)
        if not ok then return false, "ray_error" end
        if not hit then return false, "surface_missing" end
        local instanceName = string.lower(tostring(hit.Instance and hit.Instance.Name or ""))
        local materialName = string.lower(tostring(hit.Material or ""))
        local hazardous = instanceName:find("water", 1, true) or instanceName:find("lava", 1, true)
            or materialName:find("water", 1, true) or materialName:find("lava", 1, true)
        local detail = "material=" .. tostring(hit.Material) .. "|instance=" .. tostring(hit.Instance and hit.Instance:GetFullName())
        return not hazardous, detail
    end

    function Raid:RefreshFinalBossFollowGuard(island, candidate, targetModel)
        local state = self.State
        state.finalBossFollow = false
        state.finalBossIsland = nil
        state.finalBossSurfaceSafe = false
        state.finalBossSurfaceDetail = ""
        if not island or island.id ~= self.FinalIslandId or typeof(candidate) ~= "Vector3" then return false end
        local outerDistance = (candidate - island.position).Magnitude
        -- Inner-area combat already follows normally. For the final target,
        -- extend the same Heartbeat-follow behavior through the verified owned
        -- island radius instead of parking and waiting for it to return.
        if outerDistance <= self.SafeFollowIslandRadius or outerDistance > self.FinalBossFollowRadius then return false end
        local safe, detail = self:IsSafeFinalBossSurface(candidate, targetModel)
        state.finalBossIsland = island.object
        state.finalBossSurfaceSafe = safe == true
        state.finalBossSurfaceDetail = detail or ""
        state.finalBossFollow = safe == true
        local signature = tostring(safe) .. "|" .. tostring(math.floor(outerDistance + 0.5)) .. "|" .. tostring(detail)
        if signature ~= state.finalBossGuardSignature then
            state.finalBossGuardSignature = signature
            self:Trace("final_boss_guard", (safe and "follow_owned_target" or "hold_hazard")
                .. "|distance=" .. tostring(math.floor(outerDistance + 0.5)) .. "|" .. tostring(detail))
        end
        return state.finalBossFollow
    end

    function Raid:BindCombatWave(island, mobs)
        local state, root = self.State, currentRoot()
        local target, targetDistance = self:GetTrackedOwnedMob(mobs, root and root.Position or nil)
        local candidate = target and target.root and target.root.Position or nil
        if not target or typeof(candidate) ~= "Vector3" then return nil, {}, "wave_anchor_missing" end
        local distanceToIsland = (candidate - island.position).Magnitude
        local finalFollow = self:RefreshFinalBossFollowGuard(island, candidate, target.model)
        local allowedDistance = finalFollow and self.FinalBossFollowRadius or self.WaveAnchorMaxDistance
        if distanceToIsland > allowedDistance then
            self:ProbeHazardSurface(candidate, "wave_anchor_outside_owned_island", target.model)
            return nil, {}, "wave_anchor_outside_owned_island"
        end

        local islandChanged = state.combatAnchorIsland ~= island.object
        local targetChanged = state.combatTarget ~= target.model
        local anchorMissing = typeof(state.combatAnchor) ~= "Vector3"
        local now = os.clock()

        -- The controller samples targets at 4 Hz, but the Farm hover provider
        -- reads this verified target Root on every Heartbeat. Refreshing this
        -- diagnostic anchor each controller pass makes snapshots truthful while
        -- the provider prevents knockback from creating a 50–80-stud hit gap.
        state.combatAnchor = candidate
        state.combatAnchorIsland = island.object
        state.arrivalHoldCenter = nil
        state.waveGapCenter = nil
        state.waveGapIsland = nil
        state.combatTarget = target.model
        state.safeCombatIsland = island.object
        state.safeCombatIslandPosition = island.position
        -- The final target guard was evaluated before the anchor bound so a
        -- safe boss is never downgraded to a static wait merely for roaming.
        -- Only an inner-island target becomes a follow anchor. A broad valid
        -- wave can be near the boundary, but it must not pull the player there.
        if (candidate - island.position).Magnitude <= self.SafeFollowIslandRadius then
            state.safeCombatCenter = candidate
        elseif typeof(state.safeCombatCenter) ~= "Vector3" or islandChanged then
            -- Preserve an existing airborne position when possible. It is a
            -- safer fallback than inventing an island-center ground location.
            local current = currentRoot()
            state.safeCombatCenter = current and (current.Position - Vector3.new(0, self:GetRaidHoverHeight(), 0)) or island.position
        end
        state.lastReanchorAt = now
        if anchorMissing or islandChanged or targetChanged then
            if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
            self:Trace("combat_wave", (anchorMissing or islandChanged) and "anchored" or "retargeted"
                .. "|island=" .. tostring(island.id)
                .. "|distance=" .. tostring(math.floor((targetDistance or 0) + 0.5))
                .. "|position=" .. tostring(candidate))
        end

        local combatMobs = self:GetCombatClusterForTarget(mobs, target)
        local members = {}
        for _, item in ipairs(combatMobs) do table.insert(members, tostring(item and item.model)) end
        table.sort(members)
        -- Restage only when the owned group changes, not on every 0.25-second
        -- controller pass. This lets new nearby NPCs join a fast wave safely.
        state.combatStageKey = tostring(island.object) .. ":" .. tostring(target.model) .. ":" .. table.concat(members, ",")
        state.combatMobs = combatMobs
        state.combatActive = #combatMobs > 0
        return state.combatAnchor, combatMobs, nil
    end

    function Raid:FastAttackRaidMobs(mobs)
        if State.farmAutoAttack ~= true then return false, "attack_off" end
        local state, root = self.State, currentRoot()
        local tool, weaponReason = self:EquipWeapon()
        if not root or not tool then return false, weaponReason or "root_missing" end
        local attack, hit = self:GetCombatRemotes()
        if not attack or not hit then return false, "combat_remotes_unavailable" end

        local hitData, health, primary = {}, {}, nil
        local preferredParts = { "RightLowerArm", "RightUpperArm", "LeftLowerArm", "LeftUpperArm", "RightHand", "LeftHand" }
        for _, item in ipairs(mobs or {}) do
            local model, mobRoot, humanoid = item.model, item.root, item.humanoid
            if alive(model) and mobRoot and humanoid and (mobRoot.Position - root.Position).Magnitude <= self.AttackReach then
                local part = nil
                for _, partName in ipairs(preferredParts) do part = model:FindFirstChild(partName); if part then break end end
                part = part or model.PrimaryPart or mobRoot
                if part then
                    table.insert(hitData, { model, part })
                    health[model] = humanoid.Health
                    primary = primary or part
                end
            end
        end
        if not primary or #hitData == 0 then return false, "raid_mobs_out_of_range" end

        -- Match the extracted sequence: an equipped tool's click event, then
        -- RegisterAttack, then the client SendHitsToServer route when present.
        -- Each action is independently protected so a tool-specific failure
        -- never terminates the Raid controller.
        state.fastCycles = (state.fastCycles or 0) + 1
        local click = tool:FindFirstChild("LeftClickRemote")
        if click and click:IsA("RemoteEvent") then
            local delta = primary.Position - root.Position
            local direction = delta.Magnitude > 0 and delta.Unit or Vector3.zero
            local clickOk = pcall(function() click:FireServer(direction, 1) end)
            if clickOk then state.fastClickEvents = (state.fastClickEvents or 0) + 1 end
        end

        local attackOk, attackDetail = pcall(function() attack:FireServer(0) end)
        if not attackOk then return false, tostring(attackDetail or "register_attack_failed") end
        state.fastAttackEvents = (state.fastAttackEvents or 0) + 1

        local hitOk, hitDetail
        local sender = self:HasCombatRemoteThread() and self:GetSendHitsToServer() or nil
        if sender then
            hitOk, hitDetail = pcall(sender, primary, hitData)
        else
            hitOk, hitDetail = pcall(function() hit:FireServer(primary, hitData) end)
        end
        if not hitOk then return false, tostring(hitDetail or "register_hit_failed") end
        state.fastHitEvents = (state.fastHitEvents or 0) + 1

        -- At uncapped cadence, feedback is sampled rather than queued on every
        -- frame; otherwise diagnostic work itself would become the bottleneck.
        local now = os.clock()
        if now - (state.lastFeedbackQueuedAt or -math.huge) >= self.CombatFeedbackInterval then
            state.lastFeedbackQueuedAt = now
            state.pendingAttack = { at = now, health = health }
        end
        return true, sender and "send_hits" or "register_hit"
    end

    function Raid:RunCombat(generation, combatGeneration)
        local state = self.State
        while state.running and state.generation == generation and state.combatGeneration == combatGeneration do
            if state.combatActive and self:IsRaiding() and State.farmAutoAttack == true then
                local ok, reason = pcall(function() return self:FastAttackRaidMobs(state.combatMobs) end)
                if not ok then
                    -- No Remote cadence is added here. An out-of-range target
                    -- can occur for one controller sample during follow; do
                    -- not turn that expected state into an unbounded trace
                    -- flood that steals time from the user's exact task.wait()
                    -- attack cadence.
                    local now = os.clock()
                    if reason ~= "raid_mobs_out_of_range" or now - (state.lastCombatErrorTraceAt or -math.huge) >= 0.50 then
                        state.lastCombatErrorTraceAt = now
                        self:Trace("combat_error", tostring(reason))
                    end
                end
                -- This deliberate scheduler yield mirrors the extracted
                -- task.wait(0) attack cycle selected by the user.
                task.wait()
            else
                task.wait(self.CombatIdleWait)
            end
        end
    end

    function Raid:StartCombatWorker(generation)
        local state = self.State
        state.combatGeneration = (state.combatGeneration or 0) + 1
        local combatGeneration = state.combatGeneration
        task.spawn(function() self:RunCombat(generation, combatGeneration) end)
    end

    function Raid:OfferFinalBossV4(island, mobs)
        local state = self.State
        if not island or island.id ~= self.FinalIslandId or #(mobs or {}) == 0 or state.v4FinalBossSpawnObserved then return end
        -- This becomes true even when V4 is unavailable/not full: the popup is
        -- specifically about this boss spawn and must not appear later in it.
        state.v4FinalBossSpawnObserved = true
        local raceV4 = Flow.Features and Flow.Features.RaceV4
        local ready, readiness = false, "v4_feature_unavailable"
        if raceV4 and raceV4.IsReady then ready, readiness = raceV4:IsReady() end
        if not ready then
            self:Trace("v4_prompt", "not_shown|" .. tostring(readiness))
            return
        end
        local notifications = Flow.Features and Flow.Features.Notifications
        if not notifications or not notifications.Confirm then
            self:Trace("v4_prompt", "not_shown|notifications_unavailable")
            return
        end
        state.v4Prompted = true
        state.v4PromptPending = true
        local id = notifications:Confirm("Chefe da Raid apareceu", "Sua V4 está pronta. Deseja ativá-la agora?", function(confirmed)
            state.v4PromptPending = false
            if confirmed ~= true then
                self:Trace("v4_prompt", "declined_or_expired")
                return
            end
            -- Confirmation grants exactly one delayed activation window. If
            -- something spends the meter before the key is sent, this waits
            -- calmly for recovery instead of clicking or prompting again.
            if not state.running or not self:IsRaiding() then
                self:Trace("v4_prompt", "confirmed_after_raid_end")
                return
            end
            state.v4ActivationDeadline = os.clock() + self.V4ActivationWaitSeconds
            state.v4ActivationAttempted = false
            state.v4ActivationAttemptedAt = 0
            self:Trace("v4_prompt", "confirmed|wait_seconds=" .. tostring(self.V4ActivationWaitSeconds))
        end, { timeout = 6, confirmText = "Sim", cancelText = "Não" })
        self:Trace("v4_prompt", "shown|notification=" .. tostring(id) .. "|timeout=6")
    end

    function Raid:ProcessConfirmedV4Activation()
        local state = self.State
        local deadline = tonumber(state.v4ActivationDeadline) or 0
        if deadline <= 0 or state.v4ActivationAttempted == true then return end
        if not self:IsRaiding() then
            state.v4ActivationDeadline = 0
            self:Trace("v4_activation", "cancelled_raid_ended")
            return
        end
        if state.activeIslandId ~= self.FinalIslandId or state.combatActive ~= true then
            state.v4ActivationDeadline = 0
            self:Trace("v4_activation", "cancelled_final_boss_gone")
            return
        end
        if os.clock() > deadline then
            state.v4ActivationDeadline = 0
            self:Trace("v4_activation", "expired_waiting_for_energy")
            return
        end
        local raceV4 = Flow.Features and Flow.Features.RaceV4
        local ready, readiness = false, "v4_feature_unavailable"
        if raceV4 and raceV4.IsReady then ready, readiness = raceV4:IsReady() end
        if not ready then
            -- No action here: the confirmed one-minute window deliberately
            -- waits for the observed meter to become full again.
            return
        end
        local activated, detail = raceV4:Activate()
        state.v4ActivationAttempted = true
        state.v4ActivationAttemptedAt = os.clock()
        state.v4ActivationDeadline = 0
        self:Trace("v4_activation", (activated and "input_sent" or "input_failed") .. "|" .. tostring(detail or readiness))
    end

    function Raid:StepActive()
        self:ProcessConfirmedV4Activation()
        if self.LandingTestOnly == true then
            local held, reason = self:HoldNativeRaidArrivalAboveCurrent("landing_test_only")
            if not held then self:SetPhase("movement_failed", tostring(reason)); return end
            self:SetPhase("landing_test_hold", "native_transfer_observation")
            return
        end
        local owned, ownershipReason = self:EnsureOwnedRaidSession()
        if not owned then
            -- Before Island 1 is replicated the native transfer has already
            -- occurred, so retain the actual arrival point in raised hover
            -- rather than waiting unprotected at its ground/water level.
            if not self.State.activeWaveSeen then
                local held, holdReason = self:HoldNativeRaidArrivalAboveCurrent(ownershipReason)
                if not held then self:SetPhase("movement_failed", tostring(holdReason)); return end
            end
            -- No NPC movement or combat is allowed until ownership is proven.
            self:SetPhase("waiting_for_island", tostring(ownershipReason))
            return
        end
        local islands = self:GetOwnedRaidIslands()
        if #islands == 0 then
            if not self.State.activeWaveSeen then
                local held, holdReason = self:HoldNativeRaidArrivalAboveCurrent("owned_raid_locations_unavailable")
                if not held then self:SetPhase("movement_failed", tostring(holdReason)); return end
            end
            self:SetPhase("waiting_for_island", "owned_raid_locations_unavailable"); return
        end
        local mobIsland, mobs = self:GetOwnedIslandMobs(islands)
        local chosen = mobIsland or self.State.activeIsland or self:ChooseIsland(islands, false)
        if chosen and (not chosen.object or not chosen.object.Parent or not self.State.ownedIslands[chosen.object]) then chosen = self:ChooseIsland(islands, false) end
        if not chosen then
            if not self.State.activeWaveSeen then
                local held, holdReason = self:HoldNativeRaidArrivalAboveCurrent("owned_raid_island_unavailable")
                if not held then self:SetPhase("movement_failed", tostring(holdReason)); return end
            end
            self:SetPhase("waiting_for_island", "owned_raid_island_unavailable"); return
        end
        if mobIsland then chosen = mobIsland end
        self.State.activeIsland, self.State.activeIslandId = chosen, chosen.id
        if #mobs > 0 then
            self:OfferFinalBossV4(chosen, mobs)
            self.State.waveSeen = true
            self.State.activeWaveSeen = true
            self.State.waitingAtNextIsland = false
            self.State.emptySince = nil
            local anchor, combatMobs, bindReason = self:BindCombatWave(chosen, mobs)
            if not anchor then
                -- An owned mob can be pushed beyond the wave boundary between
                -- controller samples. Do not let the existing dynamic provider
                -- keep following it, and never clear hover into a falling wait.
                local held, holdReason = self:HoldSafeCombatAnchor(chosen, bindReason)
                if not held then
                    self:SetPhase("movement_failed", tostring(holdReason))
                    return
                end
                self:SetPhase("waiting_for_wave", tostring(bindReason) .. "|safe_hover")
                return
            end
            local target = combatMobs[1]
            self.State.target = target and target.model and target.model.Name or nil
            self:SetPhase("combat", "owned_island_" .. tostring(chosen.id) .. "|mobs=" .. tostring(#combatMobs))
            -- The controller target is verified from this Raid's own island.
            -- Farm follows it at Heartbeat frequency only inside the inner
            -- safety radius; edge/out-of-bounds motion resolves to a retained
            -- airborne safe anchor instead of a hazardous chase.
            local moved, reason = self:MoveAndFollowAbove(self.State.combatTarget, "Owned raid wave " .. tostring(chosen.id))
            if not moved then
                self.State.combatActive = false
                self:SetPhase("movement_failed", tostring(reason))
                return
            end
            -- Bring is limited to the controller's verified owned-wave list.
            -- The active target (including a boss) is never staged; surrounding
            -- NPCs are placed only in raycast-confirmed non-water slots.
            if State.farmBringMobs == true and farm and farm.StageExternalWave then
                local stageCenter = self:GetSafeRaidFollowCenter()
                if typeof(stageCenter) == "Vector3" then
                    local stageOk, stageDetail = pcall(function()
                        return farm:StageExternalWave("raid", combatMobs, stageCenter, self.State.combatStageKey, self.State.combatTarget)
                    end)
                    if not stageOk then self:Trace("bring_error", tostring(stageDetail))
                    elseif type(stageDetail) == "string" then self:Trace("bring_wave", stageDetail) end
                end
            end
            return
        end
        self.State.target = nil
        self:ClearCombatWave("wave_empty")
        if farm and farm.ClearExternalStage then pcall(function() farm:ClearExternalStage("raid") end) end
        local now = os.clock()
        if not self.State.emptySince then self.State.emptySince = now end
        local waiting = now - self.State.emptySince

        -- Initial entry never routes or travels before the first owned wave.
        -- It does keep the *current* position in a static hover: this is not a
        -- destination change, and prevents a resumed active Raid (whose first
        -- wave has not yet been observed by the newly loaded controller) from
        -- dropping the player into the void while Island 1 streams.
        if not self.State.activeWaveSeen and not self.State.waitingAtNextIsland then
            local heldInitial, initialReason = self:HoldWaveGapAboveCurrent(chosen)
            if not heldInitial then
                self:SetPhase("movement_failed", tostring(initialReason))
                return
            end
            self:SetPhase("waiting_for_wave", "awaiting_first_owned_wave")
            return
        end

        -- A completed live wave is different from initial passive entry: the
        -- player must remain in a safe hover while the server streams the next
        -- owned island. Previously combatActive became false, which correctly
        -- stopped attacks but also let the dynamic follow lease expire; a live
        -- trace then showed the Root falling from Y -4 to Y -992 before the
        -- next island could appear. Keep the player over the verified current
        -- island for every post-wave gap, including the short EmptyWave window
        -- and the period before Island N+1 is replicated.
        local heldGap, gapReason = self:HoldWaveGapAboveCurrent(chosen)
        if not heldGap then
            self:SetPhase("movement_failed", tostring(gapReason))
            return
        end

        -- Once a completed wave has selected a verified next island, hold the
        -- player over its center while waiting for that island's wave. No new
        -- island is selected until this one actually spawns mobs.
        if self.State.waitingAtNextIsland then
            self:SetPhase("waiting_for_wave", "awaiting_owned_wave_" .. tostring(chosen.id))
            local held, holdReason = self:MoveAndHoldAbove(chosen.position, "Owned next raid island " .. tostring(chosen.id))
            if not held then self:SetPhase("movement_failed", tostring(holdReason)) end
            return
        end

        if waiting < self.EmptyWaveSeconds then
            self:SetPhase("waiting_for_wave", "owned_island_" .. tostring(chosen.id))
            return
        end
        local nextIsland = self:ChooseIsland(islands, true)
        if nextIsland and nextIsland.id ~= chosen.id then
            self.State.activeIsland, self.State.activeIslandId = nextIsland, nextIsland.id
            self.State.activeWaveSeen = false
            self.State.waitingAtNextIsland = true
            self.State.emptySince = nil
            self:SetPhase("next_island", "owned_island_" .. tostring(nextIsland.id))
            -- This is the only no-mob travel: the preceding local wave was
            -- observed and cleared, and nextIsland is already owned/verified.
            local moved, moveReason = self:MoveAndHoldAbove(nextIsland.position, "Owned next raid island " .. tostring(nextIsland.id))
            if not moved then self:SetPhase("movement_failed", tostring(moveReason)) end
        else
            self:SetPhase("waiting_for_wave", "awaiting_next_owned_island")
        end
    end

    function Raid:Step()
        self:UpdateAttackFeedback()
        local state = self.State
        if not state.running then return false end
        local liveCharacter, liveHumanoid, liveRoot = currentCharacter(), currentHumanoid(), currentRoot()
        if not player or not player.Parent or not liveCharacter or not liveHumanoid or liveHumanoid.Health <= 0 or not liveRoot then
            self:SetPhase("character_missing", "waiting_for_character")
            return true
        end
        -- Auto Raid is independent of server type and player count.
        if self:GetLevel() < self.MinimumLevel then self:SetPhase("level_required", tostring(self.MinimumLevel)); return true end
        -- This must precede the IsRaiding branch. The server can expose
        -- IslandRaiding=true before this client receives the native move; do
        -- nothing at Castle until Root confirms that native arrival.
        if state.chipCommitted == true and state.nativeTransferConfirmed ~= true then
            local arrived, arrivalDetail = self:IsNativeRaidArrivalConfirmed()
            if not arrived then
                self:HoldForNativeRaidTransfer(arrivalDetail)
                return true
            end
            state.nativeTransferConfirmed = true
            self:Trace("native_transfer", tostring(arrivalDetail))
        end
        if self:IsRaiding() then
            if not state.wasRaiding then
                if state.awaitingNativeReturn then self:ClearNativeRaidReturnHold() end
                state.raidStartedAt = os.clock()
                state.emptySince = nil
                state.activeIsland = nil
                state.activeIslandId = nil
                state.waveSeen = false
                state.activeWaveSeen = false
                state.waitingAtNextIsland = false
                state.arrivalHoldCenter = nil
                state.v4FinalBossSpawnObserved = false
                state.v4Prompted = false
                state.v4PromptPending = false
                state.v4ActivationDeadline = 0
                state.v4ActivationAttempted = false
                state.v4ActivationAttemptedAt = 0
                state.awaitingStartUntil = 0
                state.startAttempts = 0
            end
            state.wasRaiding = true
            self:StepActive()
            return true
        end
        if state.wasRaiding then
            state.wasRaiding = false
            local held, holdReason = self:BeginNativeRaidReturnHold()
            if not held then
                self:SetPhase("native_return_hold_failed", tostring(holdReason))
                return true
            end
            self:SetPhase("awaiting_native_raid_return", "keeping_safe_until_game_returns")
            return true
        end
        if state.awaitingNativeReturn == true then
            local returned, returnReason = self:IsNativeRaidReturnConfirmed()
            if not returned then
                local held, holdReason = self:HoldForNativeRaidReturn()
                if not held then self:SetPhase("native_return_hold_failed", tostring(holdReason))
                else self:SetPhase("awaiting_native_raid_return", tostring(returnReason)) end
                return true
            end
            self:Trace("native_return", tostring(returnReason))
            self:ClearNativeRaidReturnHold()
            state.completedCount = state.completedCount + 1
            local repeatGoalReached = self:RecordRepeatCompletion()
            state.activeIsland, state.activeIslandId, state.target = nil, nil, nil
            state.emptySince = nil
            state.waveSeen = false
            state.activeWaveSeen = false
            state.waitingAtNextIsland = false
            state.arrivalHoldCenter = nil
            state.awaitingStartUntil = 0
            state.chipCommitted = false
            state.chipCommittedAt = 0
            state.nativeTransferStartedAt = 0
            state.nativeTransferConfirmed = false
            state.nativeTransferOrigin = nil
            state.startAttempts = 0
            state.v4ActivationDeadline = 0
            state.v4PromptPending = false
            self:ClearOwnedRaidSession()
            state.startedByController = false
            state.resumedActiveRaid = false
            self:CaptureIslandBaseline()
            if repeatGoalReached then
                -- Reaching a finite goal has the same safe teardown as the
                -- user turning Auto Raid off, while preserving saved progress.
                self:SetEnabled(false)
                self:SetPhase("goal_complete", "repeat_goal_reached")
                Flow:Notify({ kind = "success", title = "Auto Raid", message = "Meta de Raids concluída." })
                return true
            end
            self:SetPhase("raid_finished", "awaiting_next_chip")
            task.wait(3)
            return true
        end
        state.activeIsland, state.activeIslandId, state.target = nil, nil, nil
        if state.chipCommitted == true then
            self:HoldForNativeRaidTransfer("chip_committed_waiting_for_native_transfer")
            return true
        end
        local atSummon, summonReason = self:EnsureRaidSummonAccess()
        if not atSummon then
            self:SetPhase("summon_travel_failed", tostring(summonReason))
            return true
        end
        local chipReady, chipReason = self:EnsureChip()
        if not chipReady then self:SetPhase("chip_unavailable", tostring(chipReason)); return true end
        local chipWait = os.clock() - (state.chipObservedAt or os.clock())
        if chipWait < self.ChipStartObserveSeconds then
            -- Give the server time to start/stream the local Raid before any
            -- summon fallback is considered. No movement occurs in this state.
            self:SetPhase("awaiting_raid_start", "chip_confirmed")
            return true
        end
        local started, startReason = self:StartRaid()
        if not started then self:SetPhase("start_unavailable", tostring(startReason)) end
        return true
    end

    function Raid:Run(generation)
        while self.State.running and self.State.generation == generation do
            local ok, detail = pcall(function() return self:Step() end)
            if not ok then self:SetPhase("error", tostring(detail)) end
            task.wait(0.25)
        end
    end

    function Raid:SetRaidType(raidType)
        if type(raidType) ~= "string" or not hasValue(self.Types, raidType) then return false, "raid_type_invalid" end
        State.raidType = raidType
        Flow.Config:Save()
        return true
    end

    function Raid:SetFruitCategory(category, enabled)
        if self.FruitRanks[category] == nil then return false, "fruit_category_invalid" end
        State.raidFruitCategories = State.raidFruitCategories or {}
        State.raidFruitCategories[category] = enabled == true
        Flow.Config:Save()
        return true
    end

    function Raid:SetFruitBlocked(fruitName, blocked)
        local fruit = self:ResolveFruit(fruitName)
        if not fruit then return false, "fruit_invalid" end
        State.raidFruitBlacklist = State.raidFruitBlacklist or {}
        State.raidFruitBlacklist[fruit.name] = blocked == true
        Flow.Config:Save()
        return true
    end

    function Raid:SetFruitSelected(fruitName, selected)
        local fruit = self:ResolveFruit(fruitName)
        if not fruit then return false, "fruit_invalid" end
        State.raidSelectedFruits = State.raidSelectedFruits or {}
        State.raidSelectedFruits[fruit.name] = selected == true
        Flow.Config:Save()
        return true
    end

    function Raid:GetRepeatGoal()
        return math.max(0, math.floor(tonumber(State.raidGoal) or 0))
    end

    function Raid:GetRepeatProgress()
        return math.max(0, math.floor(tonumber(State.raidGoalProgress) or 0))
    end

    function Raid:HasReachedRepeatGoal()
        local goal = self:GetRepeatGoal()
        return goal > 0 and self:GetRepeatProgress() >= goal
    end

    function Raid:SetRepeatGoal(goal)
        goal = tonumber(goal)
        if goal == nil or goal < 0 then return false, "raid_goal_invalid" end
        State.raidGoal = math.max(0, math.min(100000, math.floor(goal)))
        local ok, detail = Flow.Config:Save()
        return ok == true, detail or (State.raidGoal == 0 and "infinite" or "saved")
    end

    function Raid:ResetRepeatProgress()
        State.raidGoalProgress = 0
        local ok, detail = Flow.Config:Save()
