]]

    -- Lucide icon subset (ISC license): rasterized locally and embedded so the
    -- standalone bundle never downloads an icon package at runtime.
    local lucideEncoded = {
        fruit = [[]],
        travel = [[]],
        maritime = [[]],
        status = [[]],
        misc = [[]],
        settings = [[]],
        target = [[]],
        cake = [[]],
        crown = [[]],
        skull = [[]],
        check = [[]],
        unavailable = [[]],
        location = [[]],
        timer = [[]],
        mobs = [[]],
        minimize = [[]],
        close = [[]],
        refresh = [[]],
        join = [[]],
        hop = [[]],
        rejoin = [[]],
        map = [[]],
        servers = [[]],
        style = [[]],
        language = [[]],
        antiAfk = [[]],
        fog = [[]],
        portal = [[]],
        speed = [[]],
        players = [[]],
        moon = [[]],
        inventory = [[]],
        accent = [[]],
    }

    local function decodeBase64(input)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        input = input:gsub("[^" .. alphabet .. "=]", "")
        local bits = input:gsub(".", function(character)
            if character == "=" then return "" end
            local value = alphabet:find(character, 1, true) - 1
            local output = ""
            for index = 6, 1, -1 do
                output = output .. (value % 2 ^ index - value % 2 ^ (index - 1) > 0 and "1" or "0")
            end
            return output
        end)
        return bits:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(byte)
            if #byte ~= 8 then return "" end
            local value = 0
            for index = 1, 8 do
                if byte:sub(index, index) == "1" then value = value + 2 ^ (8 - index) end
            end
            return string.char(value)
        end)
    end

    local function executorFunction(name)
        return Flow:GetExecutorFunction(name)
    end

    local function loadLocalAsset(path, data)
        local getAsset = executorFunction("getcustomasset") or executorFunction("getsynasset")
        local writeFile = Flow.Executor.writefile
        local isFile = Flow.Executor.isfile
        if not getAsset or not writeFile then return "" end

        local exists = false
        if isFile then
            local ok, result = pcall(isFile, path)
            exists = ok and result
        end
        if not exists then
            pcall(writeFile, path, decodeBase64(data))
        end

        local ok, asset = pcall(getAsset, path)
        return ok and asset or ""
    end

    local function loadIcon()
        return loadLocalAsset("FlowKanHub_Icon_v3.png", encoded)
    end

    local lucideAssets = {}
    for name, data in pairs(lucideEncoded) do
        lucideAssets[name] = loadLocalAsset("FlowKanHub_Lucide_" .. name .. ".png", data)
    end

    Flow.Assets = {
        Icon = loadIcon(),
        Icons = lucideAssets,
        IconSize = 512,
    }
end)(Flow)

