    function Language:GetCode()
        local code = Flow.State.language
        return self.Translations[code] and code or "en"
    end

    function Language:T(key, ...)
        local dictionary = self.Translations[self:GetCode()] or self.Translations.en
        local value = dictionary[key] or self.Translations.en[key] or key
        if select("#", ...) > 0 then
            local ok, formatted = pcall(string.format, value, ...)
            if ok then return formatted end
        end
        return value
    end

    function Language:Set(code)
        if not self.Translations[code] then return false end
        Flow.State.language = code
        return true
    end

    Flow.Language = Language
end)(Flow)

