    local function frame(parent, properties, radius)
        local object = Theme.New("Frame", properties)
        object.BorderSizePixel = 0
        object.Parent = parent
        if radius then Theme.Round(object, radius) end
        return object
    end

    local function label(parent, properties)
        local object = Theme.New("TextLabel", properties)
        object.BackgroundTransparency = 1
        object.Font = properties.Font or Enum.Font.Gotham
        object.TextColor3 = properties.TextColor3 or Theme.text
        object.TextXAlignment = properties.TextXAlignment or Enum.TextXAlignment.Left
        object.Parent = parent
        return object
    end

    local function button(parent, text, color, radius, iconAssetPath)
        local object = Theme.Button(parent, text, color)
        object.BorderSizePixel = 0
        Theme.Round(object, radius or 7)
        if iconAssetPath and iconAssetPath ~= "" then
            object.Text = "    " .. tostring(text or "")
            object.TextXAlignment = Enum.TextXAlignment.Left
            Theme.New("ImageLabel", {
                Size = UDim2.new(0, 13, 0, 13),
                Position = UDim2.new(0, 8, 0.5, -6),
                BackgroundTransparency = 1,
                Image = iconAssetPath,
                ImageColor3 = Theme.text,
                ScaleType = Enum.ScaleType.Fit,
                Parent = object,
            })
        end
        return object
    end

    local function textBox(parent, initial)
        local object = Theme.New("TextBox", {
            BackgroundColor3 = Theme.panel3,
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Font = Enum.Font.Gotham,
            Text = tostring(initial),
            TextColor3 = Theme.text,
            TextSize = 11,
            Parent = parent,
        })
        Theme.Round(object, 7)
        return object
    end

    local function optionInput(parent, title, description, value, iconAssetPath)
        local row = frame(parent, {
            Size = UDim2.new(1, 0, 0, 56),
            BackgroundColor3 = Theme.panel2,
            Active = true,
        }, 8)
        Theme.Stroke(row, Theme.border, 1, 0)
        frame(row, {
            Size = UDim2.new(0, 3, 1, -16),
            Position = UDim2.new(0, 0, 0, 8),
            BackgroundColor3 = Theme.accent,
        }, 2)
        local hasIcon = iconAssetPath and iconAssetPath ~= ""
        if hasIcon then
            Theme.New("ImageLabel", {
                Size = UDim2.new(0, 16, 0, 16),
                Position = UDim2.new(0, 14, 0, 11),
                BackgroundTransparency = 1,
                Image = iconAssetPath,
                ImageColor3 = Theme.accent2,
                ScaleType = Enum.ScaleType.Fit,
                Parent = row,
            })
        end
        label(row, {
            Size = UDim2.new(1, hasIcon and -120 or -110, 0, 18),
            Position = UDim2.new(0, hasIcon and 37 or 14, 0, 9),
            Text = title,
            TextSize = 13,
            Font = Enum.Font.GothamBold,
        })
        label(row, {
            Size = UDim2.new(1, hasIcon and -120 or -110, 0, 16),
            Position = UDim2.new(0, hasIcon and 37 or 14, 0, 30),
            Text = description,
            TextSize = 10,
            TextColor3 = Theme.muted,
        })
        local box = textBox(row, value)
        box.Size = UDim2.new(0, 82, 0, 26)
        box.Position = UDim2.new(1, -93, 0.5, -13)
        row.MouseEnter:Connect(function()
            row.BackgroundColor3 = Theme.panel3
        end)
        row.MouseLeave:Connect(function()
            row.BackgroundColor3 = Theme.panel2
        end)
        return row, box
    end

    local function buildFarmPage(farmHubPage, gui, lucide, t, setStatus, subButton, sectionHeader)
-- Farm keeps its quest, combat and configuration controls together.
-- Its executor is the local Farm feature; this page never loads a hub,
-- downloads source, or discovers unknown remotes at runtime.
sectionHeader(farmHubPage, t("farm"), "")
local farmGeneralTab = subButton(farmHubPage, t("general"), 0, 92)
local farmSettingsTab = subButton(farmHubPage, t("farm_settings"), 98, 108)
farmGeneralTab.BackgroundColor3 = Theme.accent
