farmModeButton.MouseButton1Click:Connect(function()
    local current = State.farmControlMode or "above"
    local index = 1
    for position, value in ipairs(farmModes) do if value == current then index = position break end end
    State.farmControlMode = farmModes[(index % #farmModes) + 1]
    Config:Save()
    refreshFarmMode()
end)
