Flow:Track(farmSettingsTab.MouseButton1Click:Connect(function() setFarmTab("settings") end))
task.spawn(function()
    while gui and gui.Parent do
        task.wait(0.25)
        if farmHubPage.Visible then refreshFarmUI() end
    end
end)
refreshFarmUI()

