        -- Compact status cards borrow the clear title/value hierarchy of the
        -- reference hub while keeping Flow's own red theme and no external UI.
        local function liveStatusRow(title, description, iconAssetPath)
            local row = frame(generalStatusPage, {
                Size = UDim2.new(1, 0, 0, 56),
                BackgroundColor3 = Theme.panel2,
                Active = true,
            }, 8)
            Theme.Stroke(row, Theme.border, 1, 0)
            local rail = frame(row, {
                Size = UDim2.new(0, 3, 1, -16),
                Position = UDim2.new(0, 0, 0, 8),
                BackgroundColor3 = Theme.accent,
            }, 2)
            local hasIcon = iconAssetPath and iconAssetPath ~= ""
            if hasIcon then
                Theme.New("ImageLabel", {
                    Size = UDim2.new(0, 16, 0, 16),
                    Position = UDim2.new(0, 11, 0, 11),
                    BackgroundTransparency = 1,
                    Image = iconAssetPath,
                    ImageColor3 = Theme.accent2,
                    ScaleType = Enum.ScaleType.Fit,
                    Parent = row,
                })
            end
            label(row, {
                Size = UDim2.new(1, hasIcon and -43 or -22, 0, 18),
                Position = UDim2.new(0, hasIcon and 34 or 11, 0, 9),
                Text = title,
                TextSize = 13,
                Font = Enum.Font.GothamBold,
            })
            local value = label(row, {
                Size = UDim2.new(1, hasIcon and -43 or -22, 0, 16),
                Position = UDim2.new(0, hasIcon and 34 or 11, 0, 30),
                Text = description,
                TextSize = 10,
                TextColor3 = Theme.muted,
                TextTruncate = Enum.TextTruncate.AtEnd,
            })
            return value
        end
