        local function routeName(mode)
            if mode == "portal" then return t("travel_route_portal") end
            if mode == "world_portal" then return t("travel_route_world_portal") end
            return t("travel_route_direct")
        end
        local routeReasons = {
            direct_default = "travel_reason_direct", direct_faster = "travel_reason_direct",
            portal_faster = "travel_reason_portal", world_portal_faster = "travel_reason_world_portal",
            portal_disabled = "travel_reason_portal_disabled", portal_missing = "travel_reason_portal_missing",
            portal_mastery = "travel_reason_portal_mastery", portal_cooldown = "travel_reason_portal_cooldown",
            world_portals_disabled = "travel_reason_world_portals_disabled",
            no_confirmed_world_portal = "travel_reason_no_confirmed_world_portal",
            no_island = "travel_reason_no_island",
        }
        local function routeReason(reason)
            return t(routeReasons[reason] or "travel_reason_direct")
        end
        local function formatTime(seconds)
            if type(seconds) ~= "number" or seconds == math.huge or seconds ~= seconds then return t("travel_unavailable") end
            return t("travel_time", seconds)
        end
        local function selectedPlan()
            return TravelLocations and TravelLocations:Preview() or nil
        end
        local function refreshLocationTravel()
            local destination = TravelLocations and TravelLocations:GetSelected() or nil
            if not destination then
                selectedLocationText.Text = t("selected_location_none")
                estimateDestination.Text = t("estimated_route_none")
                estimateRoute.Text = ""
                estimateTimes.Text = ""
                return
            end
            selectedLocationText.Text = t("location_selected", destination.name)
            local plan = selectedPlan()
            estimateDestination.Text = t("estimated_destination", destination.name)
            if not plan then
                estimateRoute.Text = t("estimated_route_none")
                estimateTimes.Text = ""
                return
            end
            local seconds = plan.mode == "portal" and plan.portalSeconds or (plan.mode == "world_portal" and plan.worldPortalSeconds or plan.directSeconds)
            estimateRoute.Text = t("travel_eta", formatTime(seconds), routeName(plan.mode)) .. " — " .. routeReason(plan.reason)
            estimateRoute.TextColor3 = plan.mode == "direct" and Theme.muted or Theme.success
            estimateTimes.Text = t("estimated_times", formatTime(plan.directSeconds), formatTime(plan.portalSeconds), formatTime(plan.worldPortalSeconds))
        end
        local function renderLocationSelector()
            for _, child in ipairs(locationList:GetChildren()) do
                if child:IsA("TextButton") then child:Destroy() end
            end
            if not TravelLocations then return end
            for index, destination in ipairs(TravelLocations:GetAll()) do
                local selected = State.selectedTravelLocation == destination.id
                local row = Theme.New("TextButton", {
                    Size = UDim2.new(1, 0, 0, 42),
                    BackgroundColor3 = selected and Theme.accent or Theme.panel2,
                    BorderSizePixel = 0,
                    Text = destination.name,
                    TextColor3 = Theme.text,
                    TextSize = 11,
                    Font = Enum.Font.GothamBold,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    AutoButtonColor = false,
                    LayoutOrder = index,
                    ZIndex = 153,
                    Parent = locationList,
                })
                Theme.Round(row, 7)
                row.MouseButton1Click:Connect(function()
                    local ok = TravelLocations:Select(destination.id)
                    if ok then
                        locationOverlay.Visible = false
                        refreshLocationTravel()
                        setStatus(t("saved"), Theme.success)
                    end
                end)
            end
        end
        selectLocationButton.MouseButton1Click:Connect(function()
            renderLocationSelector()
            locationOverlay.Visible = true
        end)
        locationClose.MouseButton1Click:Connect(function() locationOverlay.Visible = false end)
        onLocationTeleportToggle = function(active)
            if not active then
                locationTravelRequested = false
                if locationTravelRunning then
                    Teleport:CancelTravel("location", "toggle_disabled")
                    setStatus(t("cancelled"), Theme.muted)
                end
                return
            end
            if State.isTeleporting then
                locationTeleportToggle:Set(false, true)
                return
            end
            local destination = TravelLocations and TravelLocations:GetSelected()
            if not destination then
                locationTeleportToggle:Set(false, true)
                setStatus(t("estimated_route_none"), Theme.danger)
                return
            end
            local plan = selectedPlan()
            local seconds = plan and (plan.mode == "portal" and plan.portalSeconds or (plan.mode == "world_portal" and plan.worldPortalSeconds or plan.directSeconds)) or nil
            locationTravelRequested = true
            locationTravelRunning = true
            setStatus(plan and t("travel_eta", formatTime(seconds), routeName(plan.mode)) or t("teleporting"), Theme.muted)
            task.spawn(function()
                if not locationTravelRequested then
                    locationTravelRunning = false
                    return
                end
                local ok, reason = TravelLocations:Travel(destination)
                locationTravelRunning = false
                locationTravelRequested = false
                locationTeleportToggle:Set(false, true)
                local cancelled = reason == "cancelled" or reason == "toggle_disabled" or reason == "hub_closed"
                setStatus(ok and t("ok") or (cancelled and t("cancelled") or t("fail")), ok and Theme.success or Theme.danger)
                refreshLocationTravel()
            end)
        end

        local function formatClock(seconds)
            if type(seconds) ~= "number" or seconds < 0 or seconds == math.huge or seconds ~= seconds then return t("status_unavailable") end
            local whole = math.floor(seconds + 0.5)
            local hours = math.floor(whole / 3600)
            local minutes = math.floor((whole % 3600) / 60)
            local secs = whole % 60
            return t("status_clock", hours, minutes, secs)
        end
        local function formatStuds(distance)
            if type(distance) ~= "number" or distance < 0 or distance ~= distance then return t("status_unavailable") end
            local text = tostring(math.floor(distance + 0.5))
            while true do
                local replaced, count = string.gsub(text, "^(%-?%d+)(%d%d%d)", "%1,%2")
                text = replaced
                if count == 0 then break end
            end
            return t("distance_studs", text)
        end
        local function currentPlanSeconds(plan)
            if not plan then return nil end
            if plan.mode == "portal" then return plan.portalSeconds end
            if plan.mode == "world_portal" then return plan.worldPortalSeconds end
            return plan.directSeconds
        end
        local function refreshLiveStatus()
            local snapshot = ServerStatus and ServerStatus.GetSnapshot and ServerStatus:GetSnapshot() or nil
            local allValues = {
                statusCards.uptime, statusCards.cycle, statusCards.moon,
                statusCards.eliteHunter, statusCards.katakuri.progress, statusCards.swordDealer,
                statusCards.berries, statusCards.groundFruit, statusCards.players,
                statusCards.version, statusCards.kind, statusCards.raidMonitor,
            }
            if not snapshot then
                for _, value in ipairs(allValues) do value.Text = t("status_unavailable") end
                for _, card in pairs(eventCards) do
                    setEventCard(card, t("event_badge_unavailable"), t("event_details_unavailable"), "", "", Theme.muted, lucide.unavailable)
                end
                return
            end

            local function formatEventPosition(position)
                if not position or type(position.X) ~= "number" or type(position.Y) ~= "number" or type(position.Z) ~= "number" then
                    return t("event_position_unknown")
                end
                return t("event_position", position.X, position.Y, position.Z)
            end
            local function renderIsland(key, card, island)
                island = island or {spawned = false}
                if not island.spawned then
                    setEventCard(card, t("event_badge_unavailable"), t("island_not_spawned"), t("event_not_present"), "", Theme.muted, lucide.unavailable)
                    return
                end
                local plan = ServerStatus:PlanIslandTravel(key)
                local seconds = currentPlanSeconds(plan)
                local distance = island.distance and t("kitsune_distance", formatStuds(island.distance)) or t("kitsune_distance_unknown")
                local eta = seconds and t("kitsune_eta", formatTime(seconds), routeName(plan.mode)) or t("kitsune_eta_unknown")
                setEventCard(card, t("event_badge_present"), t("kitsune_spawned"), distance .. " · " .. eta, formatEventPosition(island.position), Theme.success, lucide.location)
            end
            local function renderPresence(key, card, names, target)
                if names and #names > 0 then
                    local plan = ServerStatus:PlanMaritimeTravel(key)
                    local seconds = currentPlanSeconds(plan)
                    local distance = target and target.distance and t("kitsune_distance", formatStuds(target.distance)) or t("kitsune_distance_unknown")
                    local eta = seconds and t("kitsune_eta", formatTime(seconds), routeName(plan.mode)) or t("kitsune_eta_unknown")
                    setEventCard(card, t("event_badge_present"), t("status_visible", table.concat(names, ", ")), t("event_detected") .. " · " .. distance .. " · " .. eta, target and formatEventPosition(target.position) or t("event_position_unknown"), Theme.success, lucide.target)
                else
                    setEventCard(card, t("event_badge_unavailable"), t("event_not_present"), t("event_details_unavailable"), "", Theme.muted, lucide.unavailable)
                end
            end

            statusCards.uptime.Text = snapshot.uptime and t("server_uptime_value", formatClock(snapshot.uptime)) or t("status_unavailable")
            statusCards.cycle.Text = snapshot.cycle and t("server_cycle_value", formatClock(snapshot.cycle.remaining)) or t("status_unavailable")
            local moon = snapshot.moon or {}
            local moonState = moon.blueMoonEnded and t("moon_ended") or (moon.isBlueMoon and t("moon_active") or t("moon_inactive"))
            statusCards.moon.Text = moon.phase and t("moon_value", moonState, tostring(moon.phase)) or moonState

            renderIsland("kitsune", eventCards.kitsune, snapshot.kitsune)
            renderIsland("mirage", eventCards.mirage, snapshot.mirage)
            renderIsland("prehistoric", eventCards.prehistoric, snapshot.prehistoric)

            local events = snapshot.seaEvents or {}
            renderPresence("seaBeast", eventCards.seaBeast, events.seaBeasts, events.seaBeastTarget)
            renderPresence("leviathan", eventCards.leviathan, events.leviathans, events.leviathanTarget)
            renderPresence("terrorShark", eventCards.terrorShark, events.terrorSharks, events.terrorSharkTarget)

            local elite = snapshot.eliteHunter or {}
            statusCards.eliteHunter.Text = elite.active and t("status_visible", table.concat(elite.names, ", ")) or (type(elite.progress) == "number" and t("event_progress", tostring(elite.progress)) or t("status_unavailable"))
            statusCards.eliteHunter.TextColor3 = elite.active and Theme.success or (type(elite.progress) == "number" and Theme.accent2 or Theme.muted)

            local katakuri = snapshot.katakuri or {}
            local katakuriProgress = type(katakuri.remaining) == "number"
            statusCards.katakuri.progress.Text = katakuriProgress and t("katakuri_remaining_total", katakuri.remaining, katakuri.required or 500) or t("status_unavailable")
            statusCards.katakuri.progress.TextColor3 = katakuriProgress and Theme.accent2 or Theme.muted
            local function renderBossField(field, present)
                local color = present and Theme.success or Theme.muted
                local icon = present and lucide.check or lucide.unavailable
                field.name.TextColor3 = color
                field.indicator.Image = icon or ""
                field.indicator.ImageColor3 = color
                field.indicator.Visible = icon and icon ~= ""
                field.fallback.TextColor3 = color
                field.fallback.Visible = not field.indicator.Visible
            end
            local cakePresent = katakuri.cakePrince and #katakuri.cakePrince > 0
            renderBossField(statusCards.katakuri.cakePrince, cakePresent)
            local doughPresent = katakuri.doughKing and #katakuri.doughKing > 0
            renderBossField(statusCards.katakuri.doughKing, doughPresent)

            local swordDealer = snapshot.swordDealer or {}
            statusCards.swordDealer.Text = swordDealer.visible and t("status_visible", table.concat(swordDealer.names, ", ")) or (swordDealer.reply or t("status_unavailable"))
            statusCards.swordDealer.TextColor3 = swordDealer.visible and Theme.success or (swordDealer.reply and Theme.accent2 or Theme.muted)

            local berries = snapshot.berries or {}
            statusCards.berries.Text = (berries.bushes or 0) > 0 and t("berries_value", berries.bushes, berries.count or 0) or t("berries_none")
            local fruit = snapshot.fruit
            statusCards.groundFruit.Text = fruit and t("fruit_status_value", fruit.name, fruit.distance and formatStuds(fruit.distance) or t("status_unavailable")) or t("fruit_missing")
            statusCards.groundFruit.TextColor3 = fruit and Theme.success or Theme.muted

            local players = snapshot.players or {}
            statusCards.players.Text = players.current and players.maximum and t("server_players_value", players.current, players.maximum) or t("status_unavailable")
            statusCards.version.Text = snapshot.placeVersion and tostring(snapshot.placeVersion) or t("status_unavailable")
            statusCards.kind.Text = snapshot.private and t("server_private") or t("server_public")

            local raidSnapshot = RaidMonitor and RaidMonitor.GetSnapshot and RaidMonitor:GetSnapshot() or nil
            if not raidSnapshot then
                statusCards.raidMonitor.Text = t("raid_monitor_idle_value")
                statusCards.raidMonitor.TextColor3 = Theme.muted
                statusCards.raidMonitorToggle:Set(false, true)
            else
                statusCards.raidMonitorToggle:Set(raidSnapshot.running, true)
                if raidSnapshot.active then
                    statusCards.raidMonitor.Text = t("raid_monitor_active_value", #(raidSnapshot.enemies or {}), tonumber(raidSnapshot.eventCount) or 0)
                    statusCards.raidMonitor.TextColor3 = Theme.success
                elseif raidSnapshot.running then
                    statusCards.raidMonitor.Text = t("raid_monitor_waiting_value", tonumber(raidSnapshot.eventCount) or 0)
                    statusCards.raidMonitor.TextColor3 = Theme.accent2
                else
                    statusCards.raidMonitor.Text = t("raid_monitor_idle_value")
                    statusCards.raidMonitor.TextColor3 = Theme.muted
                end
            end

        end

        onIslandTravelToggle = function(key, active)
            local toggle = islandTravel.toggles[key]
            if not toggle then return end
            if not active then
                islandTravel.requested[key] = false
                if islandTravel.running[key] then
                    Teleport:CancelTravel(key .. "_island", "toggle_disabled")
                    setStatus(t("cancelled"), Theme.muted)
                end
                return
            end
            if State.isTeleporting or not ServerStatus then
                toggle:Set(false, true)
                return
            end
            local plan, island = ServerStatus:PlanIslandTravel(key)
            if not island or not island.spawned or not plan then
                toggle:Set(false, true)
                setStatus(t("island_not_spawned"), Theme.danger)
                return
            end
            local seconds = currentPlanSeconds(plan)
            islandTravel.requested[key] = true
            islandTravel.running[key] = true
            setStatus(seconds and t("travel_eta", formatTime(seconds), routeName(plan.mode)) or t("teleporting"), Theme.muted)
            task.spawn(function()
                if not islandTravel.requested[key] then
                    islandTravel.running[key] = false
                    return
                end
                local ok, reason = ServerStatus:TravelToIsland(key)
                islandTravel.running[key] = false
                islandTravel.requested[key] = false
                toggle:Set(false, true)
                local cancelled = reason == "cancelled" or reason == "toggle_disabled" or reason == "hub_closed"
                setStatus(ok and t("ok") or (cancelled and t("cancelled") or t("fail")), ok and Theme.success or Theme.danger)
                refreshLiveStatus()
            end)
        end
        onMaritimeTravelToggle = function(key, active)
            local toggle = maritimeTravel.toggles[key]
            if not toggle then return end
            if not active then
                maritimeTravel.requested[key] = false
                if maritimeTravel.running[key] then
                    Teleport:CancelTravel("maritime_" .. key, "toggle_disabled")
                    setStatus(t("cancelled"), Theme.muted)
                end
                return
            end
            if State.isTeleporting or not ServerStatus then
                toggle:Set(false, true)
                return
            end
            local plan, target = ServerStatus:PlanMaritimeTravel(key)
            if not target or not target.position or not plan then
                toggle:Set(false, true)
                setStatus(t("event_not_present"), Theme.danger)
                return
            end
            local seconds = currentPlanSeconds(plan)
            maritimeTravel.requested[key] = true
            maritimeTravel.running[key] = true
            setStatus(seconds and t("travel_eta", formatTime(seconds), routeName(plan.mode)) or t("teleporting"), Theme.muted)
            task.spawn(function()
                if not maritimeTravel.requested[key] then
                    maritimeTravel.running[key] = false
                    return
                end
                local ok, reason = ServerStatus:TravelToMaritimeTarget(key)
                maritimeTravel.running[key] = false
                maritimeTravel.requested[key] = false
                toggle:Set(false, true)
                local cancelled = reason == "cancelled" or reason == "toggle_disabled" or reason == "hub_closed"
                setStatus(ok and t("ok") or (cancelled and t("cancelled") or t("fail")), ok and Theme.success or Theme.danger)
                refreshLiveStatus()
            end)
        end
        refreshLiveStatus()
        task.spawn(function()
            while gui and gui.Parent do
                task.wait(1)
                if gui and gui.Parent then refreshLiveStatus() end
            end
        end)

