        label(seasRow, {Size = UDim2.new(1, -22, 0, 14), Position = UDim2.new(0, 11, 0, 28), Text = t("server_seas_desc"), TextSize = 9, TextColor3 = Theme.muted})
        local sea1 = button(seasRow, t("sea_1"), Theme.panel3, 7)
