        label(serverActionsRow, {Size = UDim2.new(1, -22, 0, 14), Position = UDim2.new(0, 11, 0, 28), Text = t("server_actions_desc"), TextSize = 9, TextColor3 = Theme.muted})
        local serverHop = button(serverActionsRow, t("server_hop"), Theme.panel3, 7, lucide.hop)
