        serverHop.Size, serverRejoin.Size = UDim2.new(0, 142, 0, 24), UDim2.new(0, 112, 0, 24)
        serverHop.Position, serverRejoin.Position = UDim2.new(0, 11, 1, -30), UDim2.new(0, 159, 1, -30)

        local correctingOwnJob = false
        local function restoreYourJobId()
            if not TravelServers then return end
            local currentJobId = TravelServers:GetCurrentJobId()
            if yourJobInput.Text ~= currentJobId then
                correctingOwnJob = true
                yourJobInput.Text = currentJobId
                correctingOwnJob = false
            end
        end
        local function refreshServerInfo()
            if not TravelServers then return end
            local info = TravelServers:GetInfo()
            serverJobText.Text = t("server_job") .. ": " .. info.jobId
            serverPlaceText.Text = t("server_place") .. ": " .. tostring(info.placeId)
            serverVersionText.Text = t("server_version") .. ": " .. tostring(info.placeVersion)
            serverPlayersText.Text = t("server_players") .. ": " .. tostring(info.playerCount) .. "/" .. tostring(info.maxPlayers)
            serverTypeText.Text = t("server_type") .. ": " .. (info.serverType == "private" and t("server_private") or t("server_public"))
            restoreYourJobId()
        end
        yourJobInput:GetPropertyChangedSignal("Text"):Connect(function()
            if not correctingOwnJob then restoreYourJobId() end
        end)
        joinJob.MouseButton1Click:Connect(function()
            if not TravelServers then return end
            joinJob.Text = "..."
            setStatus(t("server_joining"), Theme.muted)
            task.spawn(function()
                local ok, reason = TravelServers:JoinJob(joinJobInput.Text)
                if joinJob.Parent then joinJob.Text = t("server_join_job") end
                if ok then setStatus(t("server_teleporting"), Theme.success)
                elseif reason == "job_missing" then setStatus(t("server_job_missing"), Theme.danger)
                elseif reason == "job_invalid" then setStatus(t("server_job_invalid"), Theme.danger)
                else setStatus(t("server_request_failed"), Theme.danger) end
            end)
        end)
        local function serverAction(buttonControl, method, labelKey)
            if not TravelServers or type(TravelServers[method]) ~= "function" then return end
            buttonControl.Text = "..."
            setStatus(t("server_joining"), Theme.muted)
            task.spawn(function()
                local ok = TravelServers[method](TravelServers)
                if buttonControl.Parent then buttonControl.Text = t(labelKey) end
                setStatus(ok and t("server_teleporting") or t("server_request_failed"), ok and Theme.success or Theme.danger)
            end)
        end
