        local function addFruitRow(parent, fruit, order)
            local row = frame(parent, {
                Size = UDim2.new(1, 0, 0, 56),
                BackgroundColor3 = Theme.panel2,
                LayoutOrder = order,
                Active = true,
            }, 8)
            row.MouseEnter:Connect(function()
                row.BackgroundColor3 = Theme.panel3
            end)
            row.MouseLeave:Connect(function()
                row.BackgroundColor3 = Theme.panel2
            end)
            local rarity = fruit.rarity == "mythic" and t("rarity_mythic") or (fruit.rarity == "legendary" and t("rarity_legendary") or t("rarity_common"))
            label(row, {
                Size = UDim2.new(1, -126, 0, 18),
                Position = UDim2.new(0, 11, 0, 9),
                Text = fruit.name,
                TextSize = 13,
                Font = Enum.Font.GothamBold,
            })
            label(row, {
                Size = UDim2.new(1, -126, 0, 16),
                Position = UDim2.new(0, 11, 0, 30),
                Text = rarity,
                TextSize = 10,
                TextColor3 = fruit.rarity == "mythic" and Theme.accent2 or Theme.muted,
            })
            local teleportButton = button(row, t("tp"), Theme.accent, 7, lucide.target)
            teleportButton.Size = UDim2.new(0, 48, 0, 24)
            teleportButton.Position = UDim2.new(1, -108, 0.5, -12)
            local collectButton = button(row, t("get"), Theme.accent2, 7, lucide.inventory)
            collectButton.Size = UDim2.new(0, 48, 0, 24)
            collectButton.Position = UDim2.new(1, -54, 0.5, -12)

            teleportButton.MouseButton1Click:Connect(function()
                if State.isTeleporting then return end
                teleportButton.Text = "..."
                local preview = Teleport:Plan(fruit.position, Portal, WorldPortals, false)
                local seconds = preview.mode == "portal" and preview.portalSeconds or (preview.mode == "world_portal" and preview.worldPortalSeconds or preview.directSeconds)
                local mode = preview.mode == "portal" and t("travel_route_portal") or (preview.mode == "world_portal" and t("travel_route_world_portal") or t("travel_route_direct"))
                setStatus(t("travel_eta", t("travel_time", seconds), mode), Theme.muted)
                task.spawn(function()
                    local callOk, moved, reason = pcall(function() return Finder:TravelTo(fruit, "manual") end)
                    if teleportButton.Parent then teleportButton.Text = t("tp") end
                    local cancelled = reason == "cancelled" or reason == "user_cancelled" or reason == "auto_disabled" or reason == "hub_closed"
                    setStatus(callOk and moved and t("ok") or (cancelled and t("cancelled") or t("fail")), callOk and moved and Theme.success or Theme.danger)
                end)
            end)

            collectButton.MouseButton1Click:Connect(function()
                if State.isTeleporting then return end
                collectButton.Text = "..."
                local preview = Teleport:Plan(fruit.position, Portal, WorldPortals, false)
                local seconds = preview.mode == "portal" and preview.portalSeconds or (preview.mode == "world_portal" and preview.worldPortalSeconds or preview.directSeconds)
                local mode = preview.mode == "portal" and t("travel_route_portal") or (preview.mode == "world_portal" and t("travel_route_world_portal") or t("travel_route_direct"))
                setStatus(t("travel_eta", t("travel_time", seconds), mode), Theme.muted)
                task.spawn(function()
                    local callOk, stored, reason = pcall(function() return Finder:CollectOne(fruit, "manual") end)
                    if collectButton.Parent then collectButton.Text = t("get") end
                    local cancelled = reason == "cancelled" or reason == "user_cancelled" or reason == "auto_disabled" or reason == "hub_closed"
                    setStatus(callOk and stored and t("ok") or (cancelled and t("cancelled") or t("fail")), callOk and stored and Theme.success or Theme.danger)
                end)
            end)
        end

        local function clearFruitList()
            for _, child in ipairs(fruitList:GetChildren()) do
                if child:IsA("Frame") or child:IsA("TextLabel") then child:Destroy() end
            end
        end

        local renderFruitPage
        local selectorOverlay = Theme.New("Frame", {
            Name = "FruitSelectorOverlay",
